window.SEITEN={"index.html": "Übersicht", "auftraege.html": "Aufträge", "entscheidungen.html": "Entscheidungen", "baustellen.html": "Baustellen", "verlauf.html": "Verlauf", "einstieg.html": "Was läuft & Begriffe", "wissen.html": "Wissen", "wissen-fuhrwesen.html": "Wissen: Vom Fuhrwesen", "wissen-meister.html": "Wissen: Vom Meister", "wissen-pacht.html": "Wissen: Von Pacht und Versteigerung", "wissen-leben.html": "Wissen: Vom Leben und Sterben", "wissen-werbung-und-ehe.html": "Wissen: Von Werbung und Ehe", "wissen-steuern.html": "Wissen: Von Steuern und der Stadtkasse", "wissen-schenke.html": "Wissen: Von der Schenke", "wissen-altern-lassen.html": "Wissen: Altern lassen"};
window.SUCHE=[{"p":"auftraege.html","i":"i1","x":"S3 Eine Mehrspielerpartie ★ Zu tun: irgendeinen Stand aus einer Netzwerkpartie schicken, .SRV und .SAV. offen Spielstand"},{"p":"auftraege.html","i":"i2","x":"S5 Ein Kanonenturm Zu tun: einen Stand schicken, in dem irgendwo ein Kanonenturm steht. erfüllt Spielstand"},{"p":"auftraege.html","i":"i3","x":"L0 Die Sternskala der Talente ★ Zu tun: eine Figur mit ihren Talentsternen fotografieren (halbe Sterne mit), ihren vollen Namen notieren und gleich danach speichern; zwei Figuren machen es sicher. erfüllt Spielstand"},{"p":"auftraege.html","i":"i4","x":"V1 Macht die Gunst der Arbeiter schneller? ★ Zu tun: Produktionsdauer einer Ware notieren, Prämie zahlen, Dauer erneut notieren — gern mehrmals, bis der Gunstbalken oben ist. erfüllt im Spiel"},{"p":"auftraege.html","i":"i5","x":"V2 Macht ein kranker Arbeiter langsamer? ★ Zu tun: Dauer bei gesunder Belegschaft notieren, warten bis einer erkrankt (oder Krötenschleim), Dauer erneut notieren, ohne ihn zu behandeln. offen im Spiel"},{"p":"auftraege.html","i":"i6","x":"V3 Was tut der Unkendunk wirklich? ★ Zu tun: den Unkendunk auf einen Betrieb anwenden lassen, den ihr beobachten könnt; läuft die Produktion langsamer, obwohl die angezeigte Dauer gleich bleibt?. offen im Spiel"},{"p":"auftraege.html","i":"i7","x":"V4 Die Weidenrute Zu tun: Dauer notieren, die Weidenrute auf den eigenen Betrieb anwenden, Dauer erneut notieren. erfüllt im Spiel"},{"p":"auftraege.html","i":"i8","x":"V5 Beschleunigt die Handwerkskunst? ★ Zu tun: Die bisherigen Zahlen passen, wenn Knochenhammer und Seziermesser zwischendurch gekauft wurden — die Talentwirkung ist darin nicht zu trennen. Bitte: Dauer notieren, einen Talentschritt machen, Dauer erneut notieren, und dazwischen nichts kaufen, keinen Regler im Personalbuch bewegen, keinen Untoten dazuholen. Ein Spielstand direkt danach hilft zusätzl"},{"p":"auftraege.html","i":"i9","x":"V6 Gibt es einen Regler für den Arbeitseifer? Zu tun: im Betriebsfenster nach einem Regler für Tempo, Eifer oder Schichtlänge suchen und fotografieren — auch wenn nichts da ist. offen Foto"},{"p":"auftraege.html","i":"i10","x":"R1 Wie viele Zutatenplätze ein Lager hat Zu tun: im Lager der Goldschmiede zählen, wie viele verschiedene Zutaten Platz haben (die Daten sagen 8, die Erinnerung 5). offen im Spiel"},{"p":"auftraege.html","i":"i11","x":"S1 Eine späte Partie Zu tun: erfüllt durch eine Nürnberger Partie von 1481 und 1505 — mit Erbfolge, vier Schlössern und einer überfüllten Stadt; Kölner Stände ab 1420 bleiben willkommen. erfüllt Spielstand"},{"p":"auftraege.html","i":"i12","x":"S2 Mehrere Stände einer Partie Zu tun: erfüllt durch die Nürnberger Reihe 1405, 1410, 1415. erfüllt Spielstand"},{"p":"auftraege.html","i":"i13","x":"S4 Eine andere Stadt als Köln Zu tun: erfüllt durch Nürnberg; weitere Städte bleiben willkommen. erfüllt Spielstand"},{"p":"auftraege.html","i":"i14","x":"B17 Der Preis auf dem Regalschild ★ Zu tun: das Handelsfenster fotografieren und gleich danach speichern; beides schicken. erfüllt Spielstand"},{"p":"auftraege.html","i":"i15","x":"B58 Der Preis eines fremden Betriebs ★ Zu tun: wie B17, an einem Betrieb, der nicht dir gehört. erfüllt Spielstand"},{"p":"auftraege.html","i":"i16","x":"B45 Das Bild in der Infotafel eines Raumes Laut Programm ist es ein fertiges Bild aus dem Archiv, eines je Gebäudeart. Ob das Foto des Originals genau dieses Bild zeigt, sagt ein Blick darauf. Zu tun: die Infotafel eines Gebäudes öffnen und fotografieren, so dass das Raumbild darin gut zu sehen ist. offen Foto"},{"p":"auftraege.html","i":"i17","x":"B46 Welches Bannerwappen dir gehört Zu tun: das Banner fotografieren und gleich danach speichern. erfüllt Spielstand"},{"p":"auftraege.html","i":"i18","x":"B34 Das Personalbuch in anderer Auflösung Das Bild des Buches wird vergrößert, aber sein Rand paßt dann nicht. Ein Foto in einer anderen Auflösung zeigt, ob gestreckt oder beschnitten wird. Zu tun: das Personalbuch in 800 × 600 oder 1024 × 768 fotografieren. offen Foto"},{"p":"auftraege.html","i":"i19","x":"B54 Wo ein Handelsfenster steht Bei uns genau in der Mitte. Auf zwei Fotos des Originals stand es etwas rechts unter der Mitte, aber beide Male anders. Zu tun: mehrere Handelsfenster fotografieren, an verschiedenen Gebäuden geöffnet. offen Foto"},{"p":"auftraege.html","i":"i20","x":"R2 Wo man Rohstoffe veredelt Zu tun: herausfinden, wie man im Original das Fenster „Rohstoffe veredeln“ öffnet — an welchem Gebäude, über welchen Knopf — und ein Foto davon. offen im Spiel"},{"p":"auftraege.html","i":"i21","x":"B52 Wie man aus Laden und Speichern zurückkommt Zu tun: ausprobieren: Esc, Rechtsklick, etwas anderes?. erfüllt im Spiel"},{"p":"entscheidungen.html","i":"i22","x":"Wo die Karren bewusst anders fahren Ein paar Dinge macht der Nachbau anders als das Original, weil ihm dessen interne Tafeln fehlen: wo ein Karren zuerst einkauft, welche Steuern auf Routenhandel liegen, wie oft die Aufsicht nachsieht. Bleibt das so, oder wird nachgebaut? B60"},{"p":"entscheidungen.html","i":"i23","x":"Wer Rohstoffe sammeln darf Im Original sammelt man nur an den acht Sammelstellen, etwa im Kräutergarten oder auf dem Friedhof. Bei uns darf jedes Gewerk sammeln, das eine sammelbare Zutat braucht — auch die Schänke ihre Gerste und das Waldstück sein Holz. Wie im Original binden, oder der Schänke bewusst das Sammeln lassen? B63"},{"p":"entscheidungen.html","i":"i24","x":"Hochzeitsgebühr und Prämie Die Hochzeitsgebühr und die Prämie für das Zunftmitglied des Jahres gibt es nur im Nachbau; du wolltest beide behalten. Offen ist, wie hoch sie sein sollen — bisher 500 und 1.000 Gulden. B70"},{"p":"entscheidungen.html","i":"i25","x":"Wenn die Stadtkasse leer ist Amtsträger bekommen ihr Einkommen jetzt aus der Stadtkasse, wie in der Tabelle des Originals. Reicht das Geld nicht für alle, zahlt der Nachbau die kleinen Ämter zuerst. Das Original kennt den Fall nicht, weil es das Geld einfach erschafft. So lassen? B71"},{"p":"entscheidungen.html","i":"i26","x":"Welche Steuer ein Betrieb zahlt Im Original zahlt man Gildensteuer oder Umsatzsteuer je nach seinem Gewerk. Im Nachbau kann ein Spieler Betriebe verschiedener Gewerke haben, darum entscheidet es jeder Betrieb für sich. So lassen? B72"},{"p":"entscheidungen.html","i":"i27","x":"Wenn ein Spieler pleitegeht Wer pleite ist, beginnt im Nachbau als neue Dynastie — das hat keine Vorlage im Original. Festzulegen ist, wann genau man als pleite gilt, wohin gepfändete Ware geht (bisher an den Markt) und was die neue Dynastie behält (bisher nur Name, Wappen und Gunst). B74"},{"p":"entscheidungen.html","i":"i28","x":"Prüfungs- und Gehilfengebühren Für die Meisterprüfung und für Gehilfen verlangt der Nachbau Geld: das Erschaffen kostet 2.000, das Verbessern 1.000 und das Füttern 250 Gulden. Das Original nimmt dafür nachweislich nichts. Sollen die Gebühren bleiben oder wegfallen? B80"},{"p":"entscheidungen.html","i":"i29","x":"Miete und Löhne Bei uns macht eine teure Miete in der Stadt die Löhne höher. Im Original ist es anders und jetzt gemessen: Jeder Arbeiter zahlt seine Miete selbst an die Stadtkasse, notfalls bis ins Minus, und wer arbeitslos, ledig und zu tief verschuldet ist, stirbt. Soll der Nachbau das so übernehmen? B81"},{"p":"entscheidungen.html","i":"i30","x":"Die Duelltaktik Im Original wählt man in jeder Kampfrunde neu. Bei uns legt man sie vorher fest, damit eine Netzwerkpartie nicht auf einen Spieler warten muß. Bleibt das so? C44"},{"p":"entscheidungen.html","i":"i31","x":"Entscheidungen im Prozeß Im Original fragt das Spiel jeden im Saal während der Sitzung. Bei uns gibt man seine Entscheidung vorher ab, damit niemand warten muß. Bleibt das so? C52"},{"p":"entscheidungen.html","i":"i32","x":"Der schweigende Mittler Im Original bleibt die Frage offen, bis er antwortet. Bei uns entscheidet er zur nächsten Runde von selbst, damit niemand aufgehalten wird. Bleibt das so? C87"},{"p":"entscheidungen.html","i":"i33","x":"Der Kampf mit Einheiten Im Original ist er ganz gelesen: Echtzeit ohne Runden, höchstens sechs Angreifer, feste Munition. Entschieden ist: Er wird gebaut — aber neu geplant, weil das Original ihn nicht gut umgesetzt hat. Wie er aussehen soll, ist offen. Ideen sind willkommen. C172"},{"p":"entscheidungen.html","i":"i34","x":"Wenn ein Gegenstand zu wenige Opfer findet Der Brief aus Rom und der Moschusduft wirken auf drei Personen. Findet das Original weniger, liest es durch einen Fehler Datenmüll als Person. Der Nachbau wirkt einfach nur auf die gefundenen. Nachbauen lässt sich der Fehler nicht sinnvoll — so lassen? C179"},{"p":"entscheidungen.html","i":"i35","x":"Wie Löhne die Nachfrage heben Im Original gar nicht — die Nachfrage hängt an Einwohnern, Wohnraum und Bauten. Bei uns heben Löhne die Nachfrage ein wenig, als Bremse gegen zu schnell wachsende Vermögen. Weglassen? D3"},{"p":"entscheidungen.html","i":"i36","x":"Punkte, die unter dem Boden liegen Im Original wird ein Punkt, der mehr als 30 neben dem Boden liegt, auf den Boden gesetzt. Der Nachbau vergleicht mit dem Mittel aller Punkte. Vertagt: Hier soll später womöglich ganz neu angesetzt werden. F14"},{"p":"entscheidungen.html","i":"i37","x":"Wann es hell wird Im Original dämmert es nach der Jahreszeit, und jeder Raum hat sieben Lichtstimmungen. Bei uns dämmert es immer zur selben Zeit. Das Original klingt besser, ist aber Geschmackssache — beide Fassungen sollen erst nebeneinander gezeigt werden. Vertagt. F15"},{"p":"entscheidungen.html","i":"i38","x":"Wie Figuren im Raum laufen Das Original legt über jeden Raum ein Raster von 64 × 64 Feldern; Möbel machen Felder nur teuer, nicht unpassierbar. Der Nachbau nimmt gröbere Felder und sperrt sie ganz. Was wirklich besser ist, ist noch zu klären. Vertagt. F16"},{"p":"entscheidungen.html","i":"i39","x":"Die Stadtchroniken Datierte Ereignisse der Stadtgeschichte, inzwischen ganz gelesen. Im Original wirken sie nur, wenn man das beim Spielstart so wählt, und eine Zeile fällt im Jahr nach ihrem Datum. Der Nachbau macht es bei Zeitpunkt und Wahl anders. Umstellen? F20"},{"p":"entscheidungen.html","i":"i40","x":"Drei Bildvergleiche am Hauptrechner Werkstattabläufe, Meisterbewegungen und die Drehachsen bewegter Gegenstände. Sie werden nebeneinander gerendert, und du wählst, was wie im Original aussieht. Darstellung"},{"p":"entscheidungen.html","i":"i41","x":"Wie die Einwohnerzahl wächst Das Original rechnet die Einwohnerzahl in ganzen Zahlen und Vierteljahresschritten, der Nachbau stufenlos. Der Unterschied ist höchstens gut ein Prozent. Angleichen? Stadt"},{"p":"entscheidungen.html","i":"i42","x":"Ketzerei-Akten Im Original alle vier Jahre und nur für Computerfiguren und Bürger. Bei uns jedes Jahr und nur für Spieler. Umstellen? Kirche"},{"p":"entscheidungen.html","i":"i43","x":"Klick und Anzeige im Produktionsfenster Gebaut: Ein Klick meldet wie im Original, wenn kein Platz frei ist oder Rohstoffe fehlen, und die Tafel stellt Bedarf und Bestand gegenüber. Bitte am Bild vergleichen. B19"},{"p":"entscheidungen.html","i":"i44","x":"Der Abstand zwischen zwei Knöpfen Gebaut: Der Abstand ergibt sich wie im Original aus der Breite des Feldes und der Zahl der Knöpfe — das erklärt beide Ablesungen, 21 und 8. Bitte am Bild vergleichen. B22"},{"p":"entscheidungen.html","i":"i45","x":"Das kleine Prämienfenster im Personalbuch Gebaut: Es ist die allgemeine Meldungsbox des Spiels, mit einem Zähler von 10 bis zum Bargeld, höchstens 150. Geraten ist nur, dass das Pergament mitwächst — bitte am Bild vergleichen. B40"},{"p":"entscheidungen.html","i":"i46","x":"Wie die Regler anfangs stehen Gebaut: Der Nachbau fängt jetzt mit den Werten an, die der Installer des Originals einträgt — Detailreichtum niedrig, Schatten mittel, Spielgeschwindigkeit 50 %, Maus 64 %. Bitte am Bild vergleichen. B51"},{"p":"entscheidungen.html","i":"i47","x":"Wieviel ein Klick auf ein Warenfach kauft Gebaut wie im Original: Ein einfacher Klick ändert nichts, ein Doppelklick nimmt alles, und durch Ziehen stellt man die Stückzahl ein. Beim Nachbarn kaufen geht damit erst, wenn es Beutel und Karren dort gibt. Bitte am Bild vergleichen. B56"},{"p":"entscheidungen.html","i":"i48","x":"Personal verkleinern Gebaut: Ein Klick auf ein Bildnis im Personalbuch zeigt „entlassen!“ und „befördern!“ wie im Original, und es geht genau die angeklickte Person. Geraten ist nur, wo die beiden Zeilen stehen — bitte am Bild vergleichen. C134"},{"p":"entscheidungen.html","i":"i49","x":"Berserkerwut und Eifersucht Entschieden und gebaut: genau wie im Original — auch dort, wo das Original seltsam wirkt. Die Berserkerwut verärgert den Hausherrn fast nie, und die Eifersucht macht ihr Opfer bei drei Amtsträgern beliebter. Das wird später im Spiel angesehen und neu bewertet, ob es sich richtig anfühlt. F33"},{"p":"entscheidungen.html","i":"i50","x":"Hochzeitsgebühr und Prämie bleiben Beide gibt es im Original nicht. Der Nachbau behält sie; wie hoch sie sein sollen, ist noch offen. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i51","x":"Baurabatt für Kämmerer und Baumeister Im Original bekommt ihn nur der Kämmerer, obwohl der Text ihn auch dem Baumeister verspricht. Im Nachbau bauen beide 15 Prozent billiger. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i52","x":"Ausbaupreise mit dem Baupreisniveau Im Original hängt der Preis eines Ausbaus nicht am Baupreisniveau der Stadt. Im Nachbau spielt es weiter mit. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i53","x":"Pleite heißt Neustart Erst wird gepfändet wie im Original. Reicht das nicht, beginnt der Spieler in derselben Partie als neue Dynastie, statt auszuscheiden — damit eine Partie mit mehreren Spielern nicht zerbricht. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i54","x":"Im Nachbau verschwindet kein Geld Wo das Original Geld einfach vernichtet oder aus dem Nichts erschafft, hat der Nachbau eine Kasse — die Stadt wirtschaftet wie jeder andere. Die Stadtkasse wird auch nicht aufgefüllt, wenn sie leer ist. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i55","x":"Berserkerwut und Eifersucht Beide wirken genau wie im Original, auch wo es seltsam wirkt. Später im Spiel wird neu bewertet, ob es sich richtig anfühlt. 08.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i56","x":"Der Unkendung wirkt immer Im Original wirkt er nur, wenn er zufällig an erster Stelle im Bestand der Welt liegt — oft also gar nicht. Im Nachbau halbiert er jedes Mal. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i57","x":"Wo die Warmen Socken wirken Im Original wirken sie an einer etwas anderen Auswahl von Gebäuden. Im Nachbau genau an den fünf, in denen gesammelt wird. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i58","x":"Ein Grab umbetten Pauschal 500 Gulden; der Friedhofsbesitzer verlegt kostenlos. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i59","x":"Gildensteuer erst mit Zunfthaus Gildensteuer zahlt erst, wessen Zunft ein Zunfthaus hat; davor Umsatzsteuer. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i60","x":"Anwärter für die Reichsämter Computerfiguren bewerben sich mit, damit die Ämter besetzt bleiben und der Aufstieg ein Wettbewerb ist. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i61","x":"Meldungen zum Teufelspakt Das Original sagt nichts an. Der Nachbau bestätigt die Rückzahlung, mahnt im letzten Jahr und kündigt das Unglück an. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i62","x":"Der Glaube der Heiratskandidatinnen Kandidatinnen sind ganze Personen mit eigenem Glauben, der für sie zählt. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i63","x":"Den Wohnsitz ausbauen Welche Ausbauten ein Haus bekommen kann, hängt an der Hausart; sie gehören zum Gebäude als Ganzem. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i64","x":"Der Termin der Hochzeit Die Trauung wird eine Runde vorher angekündigt, damit jeder Gast antworten kann. Im Original ist sie meist zwei Stunden nach der Verlobung. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i65","x":"Wer bei der Hochzeit traut Im Original steht dort eine Statistenfigur. Im Nachbau traut ein Amtsträger, mit Segensfrage und Einwänden. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i66","x":"Den Glauben wechseln Nur als Umtaufe in einer Kirche, gegen Geld an deren Besitzer. 06.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i67","x":"Ausbauten gehören zum Haus Ausbauten hängen am Gebäude, nicht am Besitzer: Wer umzieht, lässt sie zurück. 06.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i68","x":"Kein Schwierigkeitsgrad Der Nachbau hat keinen Regler für den Schwierigkeitsgrad und spielt fest auf „Normal“. 04.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i69","x":"Titel für das Geheimkabinett Das Geheimkabinett verlangt den Edelmann. 04.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i70","x":"Original-Spielstände laden Original- Spielstände müssen im Nachbau nicht geladen werden können. Sie dienen weiter als Messgerät. 04.10.2026 · ohne Vorlage"},{"p":"entscheidungen.html","i":"i71","x":"Text in Meldungen Blocksatz und gleich breite Knöpfe, wie im Original. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i72","x":"Der Zierat über Fenstern Schwarz, so wie man ihn aus dem Original kennt. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i73","x":"Kampf mit Einheiten Der Einheitenkampf wird gebaut, aber neu geplant, weil er im Original nicht gut umgesetzt ist. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i74","x":"Jede Kirche hat ihren Gottesdienst Im Original bekommen manche Kirchen durch einen Fehler nie einen Gottesdienst. Der Nachbau baut ihn nach und behebt den Fehler. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i75","x":"Computergegner wachsen ohne Grenze Im Original hören die Gegner um 1460 auf zu wachsen. Im Nachbau wollen sie aus Eigeninteresse immer weiter wachsen, wie der Spieler. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i76","x":"Computergegner bauen aus Die Gegner bauen ihre Betriebe aus und ziehen in größere Häuser. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i77","x":"Baupreise Gebäude kosten, was sie im Original kosten. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i78","x":"Pleite der Computergegner Auch Computergegner können pleitegehen. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i79","x":"Die Verlängerung eines Grabes Wer die Verlängerung ablehnt oder nicht antwortet, gibt das Grab zurück. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i80","x":"Die Grabmiete Die Miete richtet sich nach Vermögen und Grabart, und der Friedhof behält seinen gemessenen Anteil. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i81","x":"Beutel statt Warenlager Der Spieler trägt nur den Beutel mit Gegenständen; Waren liegen in Betrieben und auf Karren. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i82","x":"Der Partiebeginn Jeder Betrieb gehört zu Beginn jemandem; die freien bekommen Computergegner mit 3.000 Gulden. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i83","x":"Die Startwerte der Regler Der Nachbau beginnt mit den Werten, die der Installer des Originals einträgt. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i84","x":"Das Wappen Das Wappen gehört zur Dynastie, nicht zur Spielernummer. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i85","x":"Personal entlassen Man entlässt genau die Person, die man anklickt. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i86","x":"Die Anfangstalente Talente kommen aus dem Beruf oder aus dem Stammbaum, wie bei der Charaktererstellung des Originals. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i87","x":"Das Bürgerrecht kaufen Bürger wird man durch Kauf im Rathaus, nicht allein durch Vermögen. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i88","x":"Handelsrouten statt Dauerauftrag Der Dauerauftrag des Nachbaus fällt; an seine Stelle treten Handelsrouten und der Meisterauftrag wie im Original. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i89","x":"Wie Karren Rohstoffe nachkaufen Nachgekauft wird nach der Regel des Originals. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i90","x":"Das Lange Kanonenrohr Der Nachbau bietet das Lange Rohr am Kanonenturm an, mit der gemessenen Wirkung auf die Reichweite. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i91","x":"Große Bildschirme Das Original kennt nur drei kleine Auflösungen. Auf breiten Bildschirmen wächst die Oberfläche im Nachbau mit. vor Oktober · ohne Vorlage"},{"p":"entscheidungen.html","i":"i92","x":"Der Markt als ein Gebäude Im Original läuft man die sieben Marktstände einzeln ab. Im Nachbau ist der Markt ein Gebäude, und die Stände sind Reiter darin — welche Ware wo liegt, ist wie im Original. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i93","x":"Einfachere Einrichtung der Betriebe Im Original hat fast jeder Einrichtungsgegenstand eigene Voraussetzungen. Der Nachbau fasst sie zu Ausbaustufen zusammen. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i94","x":"Nur eine Währung Das Original führt sieben Stadtwährungen mit Wechselkursen. Der Nachbau rechnet überall in Gulden. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i95","x":"Nur eine Währung Das Original führt sieben Stadtwährungen mit Wechselkursen. Der Nachbau rechnet überall in Gulden. vor Oktober"},{"p":"entscheidungen.html","i":"i96","x":"Einfachere Einrichtung der Betriebe Im Original hat fast jeder Einrichtungsgegenstand eigene Voraussetzungen. Der Nachbau fasst sie zu Ausbaustufen zusammen. vor Oktober"},{"p":"entscheidungen.html","i":"i97","x":"Der Markt als ein Gebäude Im Original läuft man die sieben Marktstände einzeln ab. Im Nachbau ist der Markt ein Gebäude, und die Stände sind Reiter darin — welche Ware wo liegt, ist wie im Original. vor Oktober"},{"p":"entscheidungen.html","i":"i98","x":"Computergegner wachsen ohne Grenze Im Original hören die Gegner um 1460 auf zu wachsen. Im Nachbau wollen sie aus Eigeninteresse immer weiter wachsen, wie der Spieler. 03.10.2026"},{"p":"entscheidungen.html","i":"i99","x":"Jede Kirche hat ihren Gottesdienst Im Original bekommen manche Kirchen durch einen Fehler nie einen Gottesdienst. Der Nachbau baut ihn nach und behebt den Fehler. 03.10.2026"},{"p":"entscheidungen.html","i":"i100","x":"Kampf mit Einheiten Der Einheitenkampf wird gebaut, aber neu geplant, weil er im Original nicht gut umgesetzt ist. 03.10.2026"},{"p":"entscheidungen.html","i":"i101","x":"Kein Schwierigkeitsgrad Der Nachbau hat keinen Regler für den Schwierigkeitsgrad und spielt fest auf „Normal“. 04.10.2026"},{"p":"entscheidungen.html","i":"i102","x":"Wer bei der Hochzeit traut Im Original steht dort eine Statistenfigur. Im Nachbau traut ein Amtsträger, mit Segensfrage und Einwänden. 07.10.2026"},{"p":"entscheidungen.html","i":"i103","x":"Der Termin der Hochzeit Die Trauung wird eine Runde vorher angekündigt, damit jeder Gast antworten kann. Im Original ist sie meist zwei Stunden nach der Verlobung. 07.10.2026"},{"p":"entscheidungen.html","i":"i104","x":"Meldungen zum Teufelspakt Das Original sagt nichts an. Der Nachbau bestätigt die Rückzahlung, mahnt im letzten Jahr und kündigt das Unglück an. 07.10.2026"},{"p":"entscheidungen.html","i":"i105","x":"Wo die Warmen Socken wirken Im Original wirken sie an einer etwas anderen Auswahl von Gebäuden. Im Nachbau genau an den fünf, in denen gesammelt wird. 07.10.2026"},{"p":"entscheidungen.html","i":"i106","x":"Der Unkendung wirkt immer Im Original wirkt er nur, wenn er zufällig an erster Stelle im Bestand der Welt liegt — oft also gar nicht. Im Nachbau halbiert er jedes Mal. 07.10.2026"},{"p":"entscheidungen.html","i":"i107","x":"Im Nachbau verschwindet kein Geld Wo das Original Geld einfach vernichtet oder aus dem Nichts erschafft, hat der Nachbau eine Kasse — die Stadt wirtschaftet wie jeder andere. Die Stadtkasse wird auch nicht aufgefüllt, wenn sie leer ist. 08.10.2026"},{"p":"entscheidungen.html","i":"i108","x":"Pleite heißt Neustart Erst wird gepfändet wie im Original. Reicht das nicht, beginnt der Spieler in derselben Partie als neue Dynastie, statt auszuscheiden — damit eine Partie mit mehreren Spielern nicht zerbricht. 08.10.2026"},{"p":"entscheidungen.html","i":"i109","x":"Ausbaupreise mit dem Baupreisniveau Im Original hängt der Preis eines Ausbaus nicht am Baupreisniveau der Stadt. Im Nachbau spielt es weiter mit. 08.10.2026"},{"p":"entscheidungen.html","i":"i110","x":"Baurabatt für Kämmerer und Baumeister Im Original bekommt ihn nur der Kämmerer, obwohl der Text ihn auch dem Baumeister verspricht. Im Nachbau bauen beide 15 Prozent billiger. 08.10.2026"},{"p":"entscheidungen.html","i":"i111","x":"Hochzeitsgebühr und Prämie bleiben Beide gibt es im Original nicht. Der Nachbau behält sie; wie hoch sie sein sollen, ist noch offen. 08.10.2026"},{"p":"baustellen.html","i":"i152","x":"Am Markt kaufen und verkaufen"},{"p":"baustellen.html","i":"i153","x":"Beim Nachbarn einkaufen"},{"p":"baustellen.html","i":"i154","x":"Einem Karren eine Handelsroute geben"},{"p":"baustellen.html","i":"i155","x":"Die Handelsroute eines Karrens löschen"},{"p":"baustellen.html","i":"i156","x":"Einen Betrieb gründen"},{"p":"baustellen.html","i":"i157","x":"Einen Betrieb ausbauen"},{"p":"baustellen.html","i":"i158","x":"Arbeitsplätze einrichten"},{"p":"baustellen.html","i":"i159","x":"Einen Betrieb schließen"},{"p":"baustellen.html","i":"i160","x":"Einen Betrieb verkaufen"},{"p":"baustellen.html","i":"i161","x":"Ein Gebäude renovieren"},{"p":"baustellen.html","i":"i162","x":"Bei der Versteigerung einer Pacht bieten"},{"p":"baustellen.html","i":"i163","x":"Ein Waldstück, einen Steinbruch oder eine Mine zurückgeben"},{"p":"baustellen.html","i":"i164","x":"Einen Friedhof kaufen"},{"p":"baustellen.html","i":"i165","x":"Das Geheimkabinett bauen"},{"p":"baustellen.html","i":"i166","x":"Zwietracht säen"},{"p":"baustellen.html","i":"i167","x":"Den Glauben wechseln"},{"p":"baustellen.html","i":"i168","x":"In ein anderes Haus umziehen"},{"p":"baustellen.html","i":"i169","x":"Das eigene Haus aufwerten"},{"p":"baustellen.html","i":"i170","x":"Einen Gegenstand aus dem Beutel benutzen"},{"p":"baustellen.html","i":"i171","x":"Zum Medicus gehen"},{"p":"baustellen.html","i":"i172","x":"Eine Liebschaft beenden"},{"p":"baustellen.html","i":"i173","x":"Einen Pakt mit dem Tod schließen"},{"p":"baustellen.html","i":"i174","x":"Den Pakt abbezahlen"},{"p":"baustellen.html","i":"i175","x":"Um Sterbehilfe bitten"},{"p":"baustellen.html","i":"i176","x":"Das Bürgerrecht kaufen"},{"p":"baustellen.html","i":"i177","x":"Die Steuern festsetzen"},{"p":"baustellen.html","i":"i178","x":"Ein Gesetz vorschlagen"},{"p":"baustellen.html","i":"i179","x":"Eine Absetzung beantragen"},{"p":"baustellen.html","i":"i180","x":"Ein Amt niederlegen"},{"p":"baustellen.html","i":"i181","x":"Eine Amtsanweisung geben"},{"p":"baustellen.html","i":"i182","x":"Als Zunftmeister ein Preisgerücht streuen"},{"p":"baustellen.html","i":"i183","x":"Anklage erheben"},{"p":"baustellen.html","i":"i184","x":"Ein Pamphlet anschlagen"},{"p":"baustellen.html","i":"i185","x":"Ein Pamphlet abreißen"},{"p":"baustellen.html","i":"i186","x":"Eine Kanone bauen"},{"p":"baustellen.html","i":"i187","x":"Die Kanone ausbauen"},{"p":"baustellen.html","i":"i188","x":"Die Kanone abfeuern"},{"p":"baustellen.html","i":"i112","x":"Wie die Nachfrage mit der Stadt wächst Im Original wächst die Nachfrage mit Einwohnern, Wohnraum und Ausbau der Stadt. Die Rechnung ist gemessen, aber zwei ihrer drei Zutaten fehlen dem Nachbau noch: eine Liste aller Häuser der Stadt und die gezählten Einwohner. Erst wenn die da sind, kann die Nachfrage mitwachsen; bis dahin bleibt sie fest. A10"},{"p":"baustellen.html","i":"i113","x":"Was der erste Betrieb herstellt Im Original wählt man zu Beginn einen Beruf, sein Wappen und sein Gesicht. Der Nachbau verteilt die Waren noch reihum, und Wappen und Gesicht werden zugeteilt. B7"},{"p":"baustellen.html","i":"i114","x":"Was die Regler in den Optionen tun Inzwischen gelesen: Jeder sichtbare Regler wirkt, etwa auf die Schatten oder die Mausgeschwindigkeit. Der Nachbau merkt sich bisher nur ihre Stellung; es fehlt der Bau. B49"},{"p":"baustellen.html","i":"i115","x":"Geldsack und Warenkorb im Einkaufsfenster Der Warenkorb ist gebaut: Er wirft die eingestellten Mengen weg, im eigenen wie im fremden Betrieb. Seit der Beutel gebaut ist, lässt sich auch der Geldsack bauen, der auf den Beutel umschaltet — das geschieht im Bild, also am Hauptrechner. B55"},{"p":"baustellen.html","i":"i116","x":"Was der Unkendung genau tut Der Unkendung bremst einen fremden Betrieb für drei Stunden auf halbe Kraft und schickt die Hälfte der Arbeiter nach Hause, und erst am nächsten Morgen kommen sie wieder — das ist gelesen und gebaut. Noch vereinfacht: Bei uns hat jeder Arbeiter eine Wohnung, und die drei Stunden laufen auf der Spieluhr; beides klärt sich mit der echten Bevölkerung. Im Bild fehlen noch W"},{"p":"baustellen.html","i":"i117","x":"Wie die Partie aus der Karte beginnt Die Partie beginnt jetzt mit den Gebäuden der Kölner Karte, verteilt auf die Dynastien wie im Original, und der Meister wählt seine Ware um 8 und 13 Uhr neu. Noch geschätzt ist, welche Dynastie welches Gebäude bekommt, und was ein später beitretender Spieler erhält. B66"},{"p":"baustellen.html","i":"i118","x":"Das erste Haus Wer im Nachbau noch keinen Wohnsitz hat, bezieht sein erstes Haus sofort. Im Original hat jede Dynastie von Anfang an eins; das kommt, wenn der Spieler mit einem Haus der Karte beginnt. B68"},{"p":"baustellen.html","i":"i119","x":"Wie man um eine Pacht bietet Die Versteigerung einer Pacht ist jetzt gebaut, mit den gemessenen Regeln des Originals. Weil die Szene mit Schieberegler noch fehlt, bietet man vorerst mit einem Befehl, und jede Runde dauert höchstens eine halbe Spielstunde. Ein paar Randfälle sind geschätzt, etwa was passiert, wenn in der letzten Runde keiner mehr bietet. B76"},{"p":"baustellen.html","i":"i120","x":"Wo ein gekaufter Ausbau steht Kauft man einen Ausbau, merkt sich der Nachbau nur, dass er da ist, nicht in welchem Raum er steht, und jedes Stück gilt als neu. Im Original hat jedes Stück seinen Platz und seinen Zustand. Für den Wert des Hauses macht das fast nie einen Unterschied. B77"},{"p":"baustellen.html","i":"i121","x":"Wie das Vermögen gezählt wird Das Vermögen rechnet jetzt wie im Original: Bargeld plus der Wert der Häuser und Waren. Geschätzt ist zweierlei: Jede Ware zählt bei uns einmal, im Original je Stapel im Lager. Und Häuser zählen immer als neu, weil sie bei uns noch nicht verfallen. B78"},{"p":"baustellen.html","i":"i122","x":"Talente beim Spielbeginn Jede Figur hat jetzt eigene Talente wie im Original, und ein neu eingestellter Meister hat wie dort den ersten Grad. Vorläufig gesetzt bleibt, was erst mit dem Spielbeginn-Menü und der echten Stadtbevölkerung kommt: wie stark die Computergegner sind, wie die Heiratskandidatinnen begabt sind, und dass manche vornehme Figuren neu angelegt statt aus der Stadt genommen werden "},{"p":"baustellen.html","i":"i123","x":"Wenn Computergegner aufsteigen Die Computergegner steigen jetzt wie im Original von selbst auf, bauen aus, ziehen in bessere Häuser, tragen Titel und zahlen beim Bauen die Preise der Stadt wie ein Spieler. Vorläufig gesetzt ist: in welcher Reihenfolge sie das überlegen, dass die Spieler davon keine Nachricht bekommen, wie der Titel vererbt wird, dass ihre Bauten ohne Bauzeit sofort stehen, und das"},{"p":"baustellen.html","i":"i124","x":"Die Erstausstattung Zu Spielbeginn schenkt das Original Zutaten für 500 Gulden; das ist jetzt gebaut. Geschätzt ist dabei: Jedes Lager beginnt klein, die Preise werden jedes Mal frisch gerechnet, und alle Zutaten kommen in ein gemeinsames Rohstofflager. Das ändert sich, wenn das Lager wie im Original Plätze für jede Ware bekommt. B85"},{"p":"baustellen.html","i":"i125","x":"Ausbau von Wald, Steinbruch und Mine Ein Betrieb zu gründen kostet jetzt wie im Original so viel wie sein Gebäude. Waldstück, Steinbruch und Mine haben im Original aber nur eine einzige Stufe; der Nachbau lässt sie trotzdem zweimal ausbauen und nimmt dafür die Preise der Schneiderei. Das fällt weg, sobald die Zahl der Stufen je Betriebsart aus den Spieldaten kommt. B86"},{"p":"baustellen.html","i":"i126","x":"Wie das Zunfthaus entsteht Wie im Original baut die Stadt ein Zunfthaus, sobald ein Gewerk drei Betriebe hat, und erst dann gibt es Gildensteuer und einen Gildenmeister. Vorläufig steht das Haus beim nächsten Rundenbeginn sofort fertig da, ohne Bauzeit und ohne eigenen Platz in der Stadt, und nur in der ersten Stufe. Das ändert sich, wenn die Stadt echte Gebäude baut. B87"},{"p":"baustellen.html","i":"i127","x":"Wer in der Stadt heiratsfähig ist Im Original werden neun Kandidaten nach festen Regeln ausgewählt. Der Nachbau würfelt sechs, bis es eine ganze Stadtbevölkerung gibt. C10"},{"p":"baustellen.html","i":"i128","x":"Die Anfangstalente einer Figur Im Original wählt man bei der Charaktererstellung „Automatisch“ — dann gibt der Beruf feste Werte, ohne Würfeln — oder „Stammbaum bestimmen“: Jedes Elternteil bringt 63 Punkte mit, dazu kommen 126 zum freien Verteilen. Entschieden: wie im Original. Gebaut wird es zusammen mit der Wahl von Beruf, Wappen und Gesicht zu Beginn. C43"},{"p":"baustellen.html","i":"i129","x":"Die Leiche für die Séance Im Original sucht man eine Leiche aus den Gräbern aus, mit Bild und Talenten. Bei uns wird sie mitbezahlt, weil Tote noch keine Figuren sind. C139"},{"p":"baustellen.html","i":"i130","x":"Der Glaube der Heiratskandidatinnen Wie sehr eine Kandidatin einen Werber mag, hängt im Original auch an ihrem Glauben. Entschieden: Kandidatinnen werden ganze Personen mit eigenem Glauben, der für sie zählt — wie im Original. Das kommt mit der echten Bevölkerung; bis dahin gelten sie als katholisch. C176"},{"p":"baustellen.html","i":"i131","x":"Die Computergegner als Familien Gebaut wie im Original: Die Computergegner haben jetzt ein Oberhaupt als Figur, sterben an Überschuldung, vererben per Los, werben, heiraten und bekommen Kinder; ohne Erben erlischt das Haus. Inzwischen nachgelesen: Ob ein Computergegner um eine Frau wirbt, entscheidet im Original seine eigene Überlegung, was er als Nächstes tut, nicht ein fester Takt. Diese Überleg"},{"p":"baustellen.html","i":"i132","x":"Der Beutel des Spielers Sechs Plätze, alles bekannt und im Kern gebaut — es fehlt nur noch das Fenster dazu. F3"},{"p":"baustellen.html","i":"i133","x":"Die Maßnahmen des Zunftmeisters Das Preisgerücht ist jetzt im Spiel angeschlossen, und das Zunfthaus gibt es inzwischen auch — aber nur in der ersten Stufe. Aufwiegeln und Politik brauchen ein Zunfthaus, das man ausbauen kann. Im Bild fehlen die Knöpfe noch. F21"},{"p":"baustellen.html","i":"i134","x":"Was Gegenstände bewirken Alle 38 Wirkungen sind bekannt, 37 davon wirken inzwischen im Spiel — vom Hexerdokument über die Voodoopuppe bis zur Eifersucht. Es fehlt nur noch der Schleifstein. F23"},{"p":"baustellen.html","i":"i135","x":"Der Nebel des Grauens Die Seuchenmaschine des Totengräbers ist vollständig gemessen, bis hin zur Wahrscheinlichkeit, dass sie trifft. Der Nebel wirkt nach Entfernung — die Lage der Betriebe vom Partiebeginn kennt der Nachbau inzwischen, die später gegründeter noch nicht. Außerdem braucht er die Stadtbevölkerung als Opfer. F26"},{"p":"baustellen.html","i":"i136","x":"Das Bürgerrecht im Rathaus kaufen Das Bürgerrecht kauft man im Original im Rathaus, sobald es einem angeboten wird. Im Nachbau geht der Kauf schon, aber nur über die Tastatur — im Rathaus fehlt noch die Stelle, an der man klickt. F29"},{"p":"baustellen.html","i":"i137","x":"Auf wen man Gegenstände anwenden kann Viele Gegenstände wirkt man im Original auf eine beliebige Figur der Stadt. Bei uns geht das nur auf Spieler, weil die übrigen Figuren noch keine Talente, Aktionspunkte oder Kerkerstrafen haben. Das kommt mit der echten Bevölkerung. F30"},{"p":"baustellen.html","i":"i138","x":"Wie die Stadt lebt und stirbt Sterberegel, Überfüllung ab etwa 650 Lebenden, Waisen und Einwanderung sind im Original gelesen, aber noch nicht gebaut. Stadt"},{"p":"baustellen.html","i":"i139","x":"Bewerber für die Ämter Im Original bewerben sich täglich neue reiche Bürger und die Computergegner um Ämter. Bei uns bewirbt sich nur der Spieler. Ämter"},{"p":"baustellen.html","i":"i140","x":"Der Gehilfe aus dem Grab Im Original trägt ein Gehilfe Namen und halbe Talente des Toten. Bei uns hat ein Grab nur einen Namen, und der Gehilfe wird ausgewürfelt. Dunkle Künste"},{"p":"baustellen.html","i":"i141","x":"Kaiser und Papst als echte Figuren Im Original sind es die historischen Personen, die altern und sterben; danach bleibt der Sitz eine Weile leer. Bei uns gibt es sie nur als Titel. Ämter"},{"p":"baustellen.html","i":"i142","x":"Anwärter für die Reichsämter Im Original legt das Spiel selbst Anwärter an, damit die Reichsämter immer besetzt werden können. Bei uns kommen nur die Spieler in Frage. Entschieden: wie im Original — die Computerfiguren mischen mit, die Ämter bleiben besetzt, und wer so hoch hinaus will, muss sich gegen sie durchsetzen. Gebaut ist es noch nicht. Ämter"},{"p":"baustellen.html","i":"i143","x":"Das Zunfthaus ausbauen Im Original baut nur der Gildenmeister das Zunfthaus aus, bezahlt aus der Zunftkasse, in die auch die Miete der Arbeiter fließt; reicht sie nicht, legt er ab 2.500 Gulden selbst etwas dazu. Im Nachbau gibt es das Zunfthaus bisher nur in der ersten Stufe, ohne Zunftkasse. Wie ein Spieler als Gildenmeister ausbaut, ist noch nicht nachgelesen. Stadt"},{"p":"baustellen.html","i":"i144","x":"Computergegner leihen sich Geld Die Computergegner bauen jetzt aus und ziehen in größere Häuser, wie im Original. Fehlt ihnen dafür nur ein kleiner Rest, nehmen sie im Original einen Kredit bei einer fremden Bank. Das fehlt noch, weil es im Nachbau die Bank als Geldgeber noch nicht gibt, nur das Konto des Spielers. KI"},{"p":"baustellen.html","i":"i145","x":"Wenn Angestellte aufsteigen Im Original steigen nicht nur die Familienoberhäupter im Laufe der Zeit auf, sondern auch Meister und Arbeiter. Gebaut ist der Aufstieg bisher nur für die Oberhäupter der Computergegner; die Angestellten haben im Nachbau stattdessen ihre Lehrstufe. KI"},{"p":"baustellen.html","i":"i146","x":"Computergegner wachsen ohne Grenze Im Original gründet ein Gegner höchstens drei Betriebe, und um 1460 hört das Wachsen auf. Entschieden: bewusst anders — die Gegner sollen aus Eigeninteresse endlos wachsen wollen, wie der Spieler. Wonach sie entscheiden, ob sich eine weitere Gründung lohnt, ist eine neue Regel ohne Vorlage. KI"},{"p":"baustellen.html","i":"i147","x":"Gottesdienst und Kollekte Im Original spenden Bürger im Gottesdienst, und der Kirchenbesitzer bekommt Geld und Ansehen — nur bekommen manche Kirchen durch einen Fehler nie einen Gottesdienst. Entschieden: nachbauen und den Fehler beheben. Inzwischen ganz gelesen: Das Original würfelt für jeden einzelnen Bürger, ob er kommt und spendet. Der Nachbau hat aber keine Bürger als Figuren, gebaut werden k"},{"p":"baustellen.html","i":"i148","x":"Den Namen des Kindes wählen Im Original fragt das Spiel bei der Geburt „Wie soll Euer Sohn heißen?\". Bei uns wird der Name ausgewählt. Familie"},{"p":"baustellen.html","i":"i149","x":"Wo das Geld hinfließt Dein Grundsatz: Im Nachbau verschwindet kein Geld, und die Stadt bekommt keines aus dem Nichts — sie wirtschaftet wie jeder andere. Fast alles ist danach gebaut: Steuern, Amtseinkommen, Baugeld, Pleite mit Neustart. Inzwischen ist auch die Versteigerung der Pacht gebaut: Wer am meisten bietet, wird Eigentümer, und das Geld geht zu neun Zehnteln an die Stadt. Offen ist nur noc"},{"p":"baustellen.html","i":"i150","x":"Beim Nachbarn einkaufen Die Warenfächer funktionieren jetzt wie im Original, aber gekauft wird erst mit einem Klick auf das Ziel: den eigenen Karren vor dem Gebäude oder den Beutel. Beides hat der Nachbau dort noch nicht, darum geht der Kauf beim Nachbarn gerade gar nicht. Ein Notknopf wird bewusst nicht gebaut. Handel"},{"p":"baustellen.html","i":"i151","x":"Drinnen stimmt alles: rund sechzig Räume aus den Originaldaten, mit Einrichtung und mit ihren Leuten, die ihre Arbeitswege ablaufen. Draußen sitzt die Landschaft noch nicht sauber unter den Häusern — Höhenkarte und Gebäudeplätze passen erst ungefähr zusammen. Gelände"},{"p":"baustellen.html","i":"i189","x":"Wie schnell man zur Meisterprüfung kommt Wie lange man auf die Zulassung zur Prüfung wartet, hängt von einem Talent ab. Die Spielstände passen am besten, wenn jede Figur gleich begabt gerechnet wird, das Programm liest sich aber anders. Nachgerechnet ist inzwischen: Krankheiten, Ämter, eine verpasste Prüfung und Aktionspunkte erklären es nicht. Offen sind noch zwei Ereignisse des Programms, die da"},{"p":"baustellen.html","i":"i190","x":"Ein Rest in den Spielskripten Viele Abläufe des Originals stehen in kleinen Skripten, etwa was ein Geselle in der Werkstatt Schritt für Schritt tut. Unser Lesewerkzeug zieht diese Abläufe heraus, kennt aber ein paar Befehle noch nicht und überspringt sie — wie viele, zeigt der Balken „Skriptbefehle zugeordnet“ oben. Meist drehen oder verschieben sie Gegenstände im Raum, und welche Zahl welche Achs"},{"p":"baustellen.html","i":"i191","x":"Gleich breite Knöpfe in Meldungen Im Original sind die Knöpfe einer Meldung gleich breit und mittig, so kennt ihr sie, und so ist es gebaut. Die Stelle im Programm, die das macht, ist noch nicht gefunden. Darstellung"},{"p":"baustellen.html","i":"i192","x":"Ein unbekanntes Kennzeichen an Figuren Wer es trägt, wird beim Klick auf ein Warenbild nicht mit ausgewählt. Was es bedeutet, ist noch nicht gelesen. Technik"},{"p":"einstieg.html","i":"i193","x":"Handwerk und Betrieb Gründen, ausbauen, Personal einstellen. Jeder Angestellte ist eine Person mit Namen und Dienstjahren — nach vier Jahren wird er Geselle. Karren auf Handelsrouten und im Auftrag des Meisters, Kontor, Meisterprüfung."},{"p":"einstieg.html","i":"i194","x":"Markt und Geld Angebot, Nachfrage und wandernde Preise. Kredit und Tilgung nach Bürgertitel, Steuern, Zoll und Zehnt — und ein Zwangsvergleich, wenn gar nichts mehr geht."},{"p":"einstieg.html","i":"i195","x":"Stadt und Ämter Der Rat wählt und setzt ab, mit gewichteten Stimmen und Wahl reihum. Der Bürgermeister bestimmt Steuer und Prunk; die Gesetze greifen wirklich in die Wirtschaft ein."},{"p":"einstieg.html","i":"i196","x":"Familie und Stand Werbung, Trauung als Fest für alle, Kinder, Lehre und Studium, Erbfolge. Der Wohnsitz vom Haus bis zum Palazzo, der Titelaufstieg und die Vorrechte, die daran hängen."},{"p":"einstieg.html","i":"i197","x":"Unterwelt und Gericht Diebstahl, Sabotage, Bestechung, Erpressung, Entführung, Duell. Anklage, Prozeß, Folter und Kerker — samt der Bestechung des Kerkermeisters. Das Pamphlet am Schwarzen Brett."},{"p":"einstieg.html","i":"i198","x":"Dunkle Künste Friedhof mit Gräbern und Gehilfen, Alchemie, Séance in der Krypta, Pakt mit dem Tod, neun Krankheiten und der Medicus — und der Kanonenturm auf Burg und Schloß."},{"p":"einstieg.html","i":"i199","x":"Zu mehreren spielen Ein Server führt die Welt, mehrere Spieler hängen sich dran. Wer rausfliegt, kommt mit seiner Wertmarke zurück an denselben Platz. Die ganze Partie läßt sich speichern."},{"p":"einstieg.html","i":"i200","x":"Die Originalwelt Räume, Modelle, Texturen, Figuren und Texte kommen unverändert aus den Spieldateien. Gespielt wird Köln — die Leute laufen dieselben Arbeitswege wie im Original."},{"p":"einstieg.html","i":"b-aktionspunkte","x":"Aktionspunkte — Die Punkte, die man je Runde für Handlungen ausgibt — Bestechen, Werben, Anklagen und vieles mehr."},{"p":"einstieg.html","i":"b-bauposten","x":"Bauposten — Etwas, das im Original gemessen ist und im Nachbau noch gebaut werden muss."},{"p":"einstieg.html","i":"b-beutel","x":"Beutel — Das Inventar der Spielfigur: sechs Sorten Gegenstände zu je drei Stück."},{"p":"einstieg.html","i":"b-bevölkerung","x":"Bevölkerung — Die Bürger der Stadt als echte Figuren mit Namen, Alter und Glauben. Im Original gibt es sie; der Nachbau zählt sie bisher nur."},{"p":"einstieg.html","i":"b-bürgerrecht","x":"Bürgerrecht — Der erste Titel über dem Stand eines einfachen Einwohners. Im Original kauft man ihn im Rathaus."},{"p":"einstieg.html","i":"b-computergegner","x":"Computergegner — Die Dynastien und Figuren, die das Spiel selbst steuert."},{"p":"einstieg.html","i":"b-gelände","x":"Gelände — Die Landschaft draußen: Höhen, Wege und wie die Häuser darauf stehen."},{"p":"einstieg.html","i":"b-gemessen","x":"gemessen — Aus den Spieldateien, aus dem Programm des Originals oder am laufenden Spiel abgelesen — nicht angenommen."},{"p":"einstieg.html","i":"b-geraten","x":"geraten — Eine Zahl, die jemand angenommen hat, weil sie noch nicht gemessen war. Sie ist gekennzeichnet, bis sie gemessen ist."},{"p":"einstieg.html","i":"b-gildensteuer","x":"Gildensteuer — Die Steuer der Zünfte. Wer sie nicht zahlt, zahlt Umsatzsteuer."},{"p":"einstieg.html","i":"b-handelsroute","x":"Handelsroute — Eine feste Fahrt, die ein Karren immer wieder abfährt, mit Halt zum Laden und Abladen."},{"p":"einstieg.html","i":"b-handgriff","x":"Handgriff — Eine Handlung im Spiel, etwa „Betrieb gründen“ oder „Anklage erheben“. Im Nachbau sind alle da; manchen fehlt nur noch der Knopf im Bild."},{"p":"einstieg.html","i":"b-kleinreste","x":"Kleinreste — Einzelne offene Punkte, die nicht in der großen Liste der geratenen Zahlen stehen."},{"p":"einstieg.html","i":"b-kontor","x":"Kontor — Das Lager eines Betriebs für Waren, die gerade nicht gebraucht werden. Im Abschnitt „Im Kontor“ heißt es auch: Arbeit am Schreibtisch, ohne Spiel."},{"p":"einstieg.html","i":"b-meisterauftrag","x":"Meisterauftrag — Der Meister eines Betriebs handelt auf eigene Faust: Er schickt Karren zum Einkaufen und Verkaufen."},{"p":"einstieg.html","i":"b-nachbau","x":"Nachbau — OpenGilde: das Spiel, neu geschrieben, das genauso funktionieren soll wie das Original."},{"p":"einstieg.html","i":"b-original","x":"Original — „Die Gilde 1400“ aus dem Jahr 2002, so wie es auf der CD war."},{"p":"einstieg.html","i":"b-proben","x":"Proben — Kleine Prüfprogramme, die nach jeder Änderung nachrechnen, ob der Nachbau noch tut, was er soll."},{"p":"einstieg.html","i":"b-reichsämter","x":"Reichsämter — Die höchsten Ämter über der Stadt, bis hinauf zum Kurfürsten."},{"p":"einstieg.html","i":"b-spielstand","x":"Spielstand — Eine gespeicherte Partie des Originals. Der Nachbau liest daraus tausende Zahlen auf einmal."},{"p":"einstieg.html","i":"b-séance","x":"Séance — In der Krypta befragt man die Geister — und kann dort auch den Teufelspakt schließen."},{"p":"einstieg.html","i":"b-teufelspakt","x":"Teufelspakt — Geld vom Teufel, das in drei Jahren zurückzuzahlen ist. Sonst trifft die Familie ein großes Unglück."},{"p":"einstieg.html","i":"b-zunfthaus","x":"Zunfthaus — Das Haus einer Zunft. Es entsteht, sobald ein Gewerk drei Betriebe in der Stadt hat."},{"p":"wissen-fuhrwesen.html","i":"i201","x":"I Drei Karren Handkarren Handelskarren Pferdekarren Preis 400 800 1.500 Ladeplätze 1 2 3 Stück je Platz 15 20 25 zusammen 15 40 75 Jeder Platz faßt eine Warensorte. Die volle Ladung erreicht also nur, wer ebenso viele Sorten auflädt, wie der Karren Plätze hat. Ein Gebäude hält höchstens drei Karren — „bereits 3 Fuhrleute angestellt\". Gekauft wird nur im eigenen Betrieb, und der Karren steht sofort"},{"p":"wissen-fuhrwesen.html","i":"i202","x":"II Wie schnell er fährt Auf demselben Boden, ohne Deichsel, der heile Handkarren gleich 100: Zustand Hand Handel Pferd heil (100) 100 121 120 halb (50) 82 104 90 hinüber (0) 64 86 60 Der Handelskarren ist bei jedem Zustand der schnellste. Der Pferdekarren hält nur heil mit ihm Schritt; er leidet unter dem Verschleiß am stärksten und fällt unter Zustand 20 sogar hinter den Handkarren. Wer schnell s"},{"p":"wissen-fuhrwesen.html","i":"i203","x":"III Was ihn schneller macht, was ihn bremst Schneller machen ihn allein die Deichseln der Lagergebäude — und nur für Karren, die in diesem Lager zu Hause sind. Ein Werkstattkarren bekommt nie einen Aufschlag. Heimat schneller um Lagerschuppen (einspännige Deichsel) 30 % Lagerhaus (dazu zweispännig) 55 % Lagerhalle (dazu vierspännig) 80 % Der Aufschlag gilt mal dem Zustand des Lagers: Eine Lagerhal"},{"p":"wissen-fuhrwesen.html","i":"i204","x":"IV Der Zustand Der grüne Balken unter dem Karrenbild läuft von 0 bis 100. Er sinkt nicht gleichmäßig: Bei jeder Ankunft verliert der Karren mit knapp einem Viertel Wahrscheinlichkeit (24 %) zwei Punkte, sonst nichts. Der Balken steht also still und springt dann. Ohne Pannen gerechnet braucht ein neuer Karren rund 150 Fahrten, bis er in den gefährlichen Bereich kommt. Der Zustand wirkt dreifach: au"},{"p":"wissen-fuhrwesen.html","i":"i205","x":"V Der Zusammenbruch „Wegen seines schlechten Zustandes ist einer Eurer Karren zusammengebrochen! Alle Waren sind verloren\" — und der Karren mit ihnen. Er verschwindet aus seinem Gebäude. Zustand Gefahr 29 und mehr keine 28 3 % 20 30 % 10 63 % 0 97 % Über 28 bricht kein Karren zusammen."},{"p":"wissen-fuhrwesen.html","i":"i206","x":"VI Gewürfelt wird nur auf langen Fahrten Unterwegs sieht das Spiel in festen Abständen nach, ob der Karren angekommen ist — beim schnellsten Spieltempo alle 7½ Minuten, das erste Mal beim Losfahren. Zusammenbruch und Panne werden genau einmal gewürfelt, beim fünften Nachsehen, also eine halbe Stunde nach der Abfahrt. Kurze Wege sind sicher. Kommt der Karren binnen gut zwanzig Minuten an, wird gar "},{"p":"wissen-fuhrwesen.html","i":"i207","x":"VII Die Panne Der zweite Wurf fällt im selben Augenblick und trifft auch heile Karren. Schützen kann Euch der Unfallschutz des Heimatgebäudes — dieselben Ausbauten, die Eure Arbeiter vor Unfällen bewahren, die Schürze etwa. In fast allen Gebäuden läßt er sich auf das Höchstmaß ausbauen. Zustand ohne Schutz voller Schutz 100 4 % 0 80 23 % 0 58 44 % 0 50 51 % 13 % 20 80 % 65 % 0 99 % 99 % Schnee und"},{"p":"wissen-fuhrwesen.html","i":"i208","x":"VIII Ausbessern Der Knopf Reparieren erscheint nur im eigenen Betrieb und ist nur hell, wenn ein markierter Karren unter 100 steht. Ausgebessert wird immer ganz und vorher in einem Betrag bezahlt. je Punkt von 0 auf 100 Handkarren 3,2 320 Handelskarren 6,4 640 Pferdekarren 12 1.200 Das sind 0,8 % des Kaufpreises je Punkt — ein Wrack instand zu setzen kostet 80 % eines neuen. Dafür dauert es: beim "},{"p":"wissen-fuhrwesen.html","i":"i209","x":"IX Die Handelsroute Der Routenschalter am Karren öffnet das Routenfenster mit einer Stadtkarte. Der erste Halt ist immer der Heimatbetrieb, und die Route ist sofort aktiv. Neue Halte kommen stets hinten dazu, jedes Gebäude nur einmal, höchstens acht. Umsortieren kann man nicht. Anfahren läßt sich fast jedes Gebäude der Stadt, gleich wem es gehört — nur kein Wohnhaus, kein Wohnsitz, kein Rathaus, k"},{"p":"wissen-fuhrwesen.html","i":"i210","x":"X Wie die Route gefahren wird Eine Aufsicht geht beim schnellsten Tempo alle 17½ Minuten alle Karren durch. Ein Karren kommt nur dran, wenn er steht. Am Halt wird zuerst abgeladen, dann, falls geschlossen ist, in Viertelstunden auf die Öffnung gewartet, dann aufgeladen. Je Halt steht der Karren nach der Rechnung eine gute Viertel- bis halbe Stunde. Vor jedem Umlauf wartet er am Heimatbetrieb, und "},{"p":"wissen-fuhrwesen.html","i":"i211","x":"XI Die Route bessert selbst aus Steht ein Routenkarren, würfelt die Aufsicht bei jedem Durchgang, ob sie ihn ausbessert — an Ort und Stelle, ohne Fahrt, ohne Meldung: Zustand je Durchgang 71 und mehr nie 70 3 % 60 34 % 50 66 % unter 40 immer Der Preis ist derselbe wie im Fenster, die Arbeit dauert etwas länger, gut sechs Minuten je Punkt. Reicht Euer Geld nicht, wird trotzdem ausgebessert — die Za"},{"p":"wissen-fuhrwesen.html","i":"i212","x":"XII Fernhandel Die drei Kontore stehen an den Kölner Stadttoren: Augsburg im Süden, Dresden im Osten, Hannover im Norden. Die Reise in die fremde Stadt endet dort — eine eigene Reisezeit gibt es nicht. Auf der Karte erscheinen die Kontore nur, wenn Ihr ein Lagergebäude besitzt. Sie gehören der Stadt, und gehandelt wird zu den Preisen und in der Währung der fremden Stadt. Von Hand hinschicken läßt "},{"p":"wissen-fuhrwesen.html","i":"i213","x":"XIII Wenn ein Meister mitredet Stellt Ihr einen Meister ein, dessen Brief auf „Darf sich einmischen\" steht, übernimmt er die Karren seines Betriebs. Ihr seht sie dann nur noch: keine Route, keine Eskorte, kein Be- und Entladen — „Dieser Karren wird von einem Meister benutzt!\". Eine eingerichtete Route bleibt liegen, solange er da ist. Der Meister wird ab halb sieben tätig, verkauft am Markt zu 90 "},{"p":"wissen-fuhrwesen.html","i":"i214","x":"XIV Die Eskorte Der Knopf unten links am Karren schaltet reihum: ohne, leicht, schwer. Die „sehr schwere Eskorte\" steht zwar in den Texten, kein Weg im Spiel führt zu ihr. Bezahlt wird beim Losschicken, ein Anteil am Wert der Ladung. Dabei zählt jede Ladung mindestens als 1.000 und höchstens als 8.000 Gulden: Eskorte Anteil kostet leicht 5 % 50 – 400 schwer 10 % 100 – 800 Ein leerer Karren fährt u"},{"p":"wissen-fuhrwesen.html","i":"i215","x":"XV Wen die Räuber wählen Räuber legen sich auf die Lauer, jeweils zwei Runden lang, und schauen etwa alle Viertelstunde nach Beute. Sie sehen dabei jeden fahrenden, beladenen Karren der ganzen Karte — die eigenen ausgenommen. Genommen werden Karren, die nahe am Lauerplatz vorbeifahren, oder solche, deren Ladung in ihr Wertband paßt. Dieses Band hängt am Talent Bei Nacht und Nebel: Die geübtesten B"},{"p":"wissen-fuhrwesen.html","i":"i216","x":"XVI Im Überfall „Einer Eurer Transporte wird von hinterhältigen Räubern überfallen!\" Dann habt Ihr vier Knöpfe: Knopf Flucht gelingt verloren Wenige Waren zurücklassen 1 % 10 % Einige Waren 46 % 50 % Viele Waren 90 % 90 % Euch mutig zum Kampfe stellen! — — „Viele\" nennt im Text 80 % des Werts, nimmt aber 90 % jedes Stapels, und von jedem Stapel mindestens ein Stück. Mißlingt die Flucht — „Die Ladu"},{"p":"wissen-fuhrwesen.html","i":"i217","x":"XVII Beute und Folgen Nach der Flucht geht der zurückgelassene Anteil in das Lager der Räuber. Gewinnt der Räuber den Kampf, nimmt er alle ganzen Stapel aller Karren — jeden, der ganz in sein Lager paßt. Auch wenn Ihr siegt, gehen die Stapel verloren, die ein Räuber im Kampf aufgehoben und nicht wieder fallen gelassen hat. Der Karren selbst bleibt Euch; die Fuhrleute kämpfen nicht und sterben nich"},{"p":"wissen-fuhrwesen.html","i":"i218","x":"XVIII Kleinigkeiten Ein Karren kehrt nie von selbst heim. Er bleibt im letzten Ziel stehen, am Markt sichtbar auf der Straße, in einem Gebäude unsichtbar. „Schnell dorthin\" im Personalbuch holt den Karren nicht; es springt nur mit der Ansicht hin. Fuhrleute haben keinen Namen und bekommen keinen Lohn. Die Plane trägt die Farbe Eurer Dynastie. Der Warenkorb im Transportfenster wirft Ware weg, er la"},{"p":"wissen-fuhrwesen.html","i":"i219","x":"XIX Sieben Ratschläge Setzt Karren auf eine Route. Sie bessert selbst aus und läßt keinen unter 40 losfahren — so bricht keiner zusammen. Und am Markt verkauft sie besser als Ihr von Hand. Baut Unfallschutz in die Heimat. Er schützt die Arbeiter und die Karren zugleich. Nehmt für Tempo den Handelskarren, für Menge den Pferdekarren — und haltet diesen heil. Lange Fahrten sind die gefährlichen. Ein "},{"p":"wissen-meister.html","i":"i220","x":"I Wer einen Betrieb führt Solange kein Meister eingestellt ist, heißt es: „Ihr leitet diesen Betrieb selbst!\" Dann teilt niemand Eure Leute ein. Wer keiner Ware zugewiesen ist, steht herum — seine Karte zeigt weder Werkzeug noch Ware — und bekommt seinen Lohn trotzdem. Ein eingestellter Meister übernimmt die Führung, aber nur, wenn sein Meisterbrief auf „Darf sich in den Betrieb einmischen\" steht."},{"p":"wissen-meister.html","i":"i221","x":"II Wen Ihr bekommt Er kommt immer mit dem höchsten Grad, den sein Handwerk kennt — in Gießerei, Schmiede und Goldschmiede ein Meisterschmied, in der Tischlerei ein Kunsttischler, in der Schänke ein Patron. Wählen läßt sich der Grad nicht. Zuerst sucht das Spiel in der Stadt jemanden, der genau diesen Grad trägt und frei ist. Erst wenn keiner paßt, kommt ein Neuer, achtzehn Jahre alt. Er tritt so g"},{"p":"wissen-meister.html","i":"i222","x":"III Was er kostet Der Preis hängt am Schwierigkeitsgrad. In den meisten Betrieben: Schwierigkeitsgrad Anwerben Sehr leicht 462 Leicht 693 Normal 924 Schwer 1.155 Sehr schwer 1.386 Beim Waldstück und beim Steinbruch ist er dreimal so teuer. Das Geld bekommt der Meister selbst, als Handgeld — es verschwindet nicht."},{"p":"wissen-meister.html","i":"i223","x":"IV Er arbeitet nicht mit Ein Meister, den Ihr anwerbt, bringt kein eigenes Handwerk mit. Er teilt ein, aber er steht an keiner Ware und erscheint nicht unter den Karten Eurer Leute. Die Behandlung aus dem Personalbuch trifft ihn nicht. Sie wirkt alle sechzig Arbeitsminuten auf jeden, der an einer laufenden Ware steht — und zwar für jede Ware eigens gezählt. Eine Prämie dagegen teilt sich auch auf "},{"p":"wissen-meister.html","i":"i224","x":"V Der Meisterbrief Der Brief gehört dem Gebäude, nicht dem Mann. Ein neuer Meister übernimmt, was dort eingestellt ist; wer die Schalter umlegt, stellt Gebäude und Meister zugleich um. Schalter ohne ihn Einmischen tut der Meister gar nichts Personal stellt er niemanden ein Karren kauft er keine Karren — außer im Lager Erweiterungen baut er nicht aus und renoviert nicht Beim Bau eines Betriebs ist "},{"p":"wissen-meister.html","i":"i225","x":"VI Sein Tag wann was er tut ständig, ab halb sieben zieht alle Leute im Gebäude ab und verteilt sie neu; kauft Lagerplätze etwa jede Stunde bessert Karren aus 7, 12 und 18 Uhr stellt Leute ein, baut aus, renoviert 8 und 13 Uhr wählt die Ware neu jede ungerade Stunde holt Karren heim, kauft Karren, prüft den Verkauf ab 20 Uhr gibt einen Handel auf, der nichts findet Eingestellt wird bis zur Höchstz"},{"p":"wissen-meister.html","i":"i226","x":"VII Welche Ware er herstellt Er bleibt bei seiner Ware, solange sie herstellbar ist. Neu gewählt wird nur um 8 und um 13 Uhr — oder wenn die laufende Ware nicht mehr geht. Dann würfelt er nach Euren Warenanteilen: Eine Ware mit 40 Anteilen kommt doppelt so oft dran wie eine mit 20. Angefangen wird eine Ware nur, wenn ihre Zutaten für einen vollen Gang im Lager liegen; fehlt etwas, kauft er erst na"},{"p":"wissen-meister.html","i":"i227","x":"VIII Wie er einteilt Bei jedem Uhrschritt zieht er alle Leute ab, die im Gebäude stehen, und stellt sie wieder hin — beim schnellsten Spieltempo alle zweieinhalb Spielminuten. Meist an dieselbe Ware. An einer Ware stehen höchstens acht Leute. Die Zutaten werden erst mit dem fertigen Stück verbraucht. Bricht eine Herstellung ab, geht nur die angefangene Arbeit verloren; die Zutaten liegen noch im L"},{"p":"wissen-meister.html","i":"i228","x":"IX Wie er einkauft Er kauft eine Zutat nach, sobald weniger als vier Gänge davon im Lager liegen oder unterwegs sind. Aufgefüllt wird dann auf einen halben freien Lagerplatz, begrenzt vom Budget. Er kauft auch aus den Zutatenlagern der Konkurrenz — dort zum Stadtpreis, am Markt zu 110 %. Liegt die Zutat in einer fremden Werkstatt, geht er nach der Rechnung des Programms dorthin und nicht zum Markt"},{"p":"wissen-meister.html","i":"i229","x":"X Wann er verkauft Geprüft wird jede ungerade Stunde, Ware für Ware — und zwar nur mit Karren, die in diesem Augenblick frei daheim stehen. Verkauft wird nur am Markt, zu 90 % des Stadtpreises; an eine andere Werkstatt verkauft er nie. Anlaß was er verkauft der Stadtpreis erreicht Euer Verkaufsniveau den ganzen Bestand Budget unter 100 oder Euer Bargeld unter 250 Gulden so viel, bis er auf rund 1."},{"p":"wissen-meister.html","i":"i230","x":"XI Er nimmt Euch die Karren Ein angestellter Meister, der sich einmischen darf, übernimmt alle Karren seines Betriebs. Ihr seht sie dann nur noch: „Dieser Karren wird von einem Meister benutzt!\" keine Handelsroute — eine eingerichtete bleibt liegen, solange er da ist, keine Eskorte, kein Beladen, kein Abladen, keine Meldungen: weder Ankunft noch Panne. Legt Ihr „Einmischen\" aus, habt Ihr die Karre"},{"p":"wissen-meister.html","i":"i231","x":"XII Was er mit den Karren tut Er schickt jeden Karren mit einem eigenen Auftrag los: bis zu drei Waren zum Verkauf und drei zum Einkauf. Ein Karren fährt erst wieder, wenn sein Auftrag erledigt ist. Zum Markt schickt er ihn zum nächstgelegenen, nach Luftlinie. Findet er nichts, wartet er eine halbe Stunde, höchstens viermal. Verlorene Karren holt er jede ungerade Stunde heim. Wie viele solcher Auf"},{"p":"wissen-meister.html","i":"i232","x":"XIII Wann er Karren kauft Nur mit dem Schalter Karren, und in dieser Reihenfolge: Kein Karren im Betrieb: sofort ein Handkarren — ohne aufs Budget zu sehen, und auch dann, wenn Ihr ihn nicht bezahlen könnt. Schon einer da: selten ein Handelskarren — im günstigsten Fall mit 2,4 % je Runde, im Mittel also nach gut vierzig Runden, und nur, wenn das Budget mehr als das Doppelte des Preises (800 Gulden"},{"p":"wissen-meister.html","i":"i233","x":"XIV Eine Anschaffung je Runde Ausbau, Renovierung, Lagerplätze, Lagererweiterung und ein weiterer Karren teilen sich eine Anschaffung je Runde; ist sie verbraucht, stellt er auch niemanden mehr ein, solange schon Leute da sind. Die Lagerkäufe stehen vorn und kommen meist schon vor sieben Uhr zum Zug. Solange es Lager zu kaufen gibt, kommt kein zweiter Karren. Ausbauen und renovieren darf er in Eur"},{"p":"wissen-meister.html","i":"i234","x":"XV Was er nicht tut Er bewaffnet praktisch niemanden. Der Meister einer Diebesgilde oder Raubritterfeste kauft Waffen ins Lager, teilt sie aber nicht aus: Er sieht nur beim ersten Mann nach, ob der ein Richtschwert oder eine Richtaxt trägt, und gibt auf, wenn nicht. Die Spielstände passen dazu, beweisen es aber nicht. Er beliefert kein Kontor. Der Lagermeister eines Computergegners plant Fernhande"},{"p":"wissen-meister.html","i":"i235","x":"XVI Kleinigkeiten In der Netzpartie führt jeder Rechner die Meister seines eigenen Spielers; Warenanteile und Verkaufsniveau gehen gar nicht über das Netz. Stirbt der Meister oder geht er, bleibt der Brief am Gebäude — der nächste bekommt dieselben Schalter. Waldstück, Steinbruch und Mine der Stadt bekommen ihren Meister von selbst."},{"p":"wissen-meister.html","i":"i236","x":"XVII Sieben Ratschläge Stellt einen Meister ein, sobald Ihr mehr Leute habt, als Ihr selbst einteilen mögt. Ohne ihn stehen sie untätig und kosten trotzdem Lohn. Setzt das Verkaufsniveau bewußt. Bei 100 % verkauft er, sobald der Grundpreis erreicht ist — wer mehr will, stellt es höher. Setzt unerwünschte Waren auf null und haltet ihre Zutaten knapp — sonst kann er sie über den Rückfall doch herste"},{"p":"wissen-pacht.html","i":"i237","x":"I Es gibt keine Jahrespacht Das Gesetz heißt „Pachtpreise“, der Beamte heißt Pachtmeister, und jeder Spieler stellt sich darunter eine jährliche Abgabe vor. Die gibt es nicht. Die Stadt setzt ein Waldstück, einen Steinbruch oder eine Mine zur Versteigerung, wer gewinnt, zahlt sein Gebot einmal — und gehört ihm die Stätte danach. Nicht auf Zeit, sondern als Eigentum: Eine Laufzeit, nach der sie an "},{"p":"wissen-pacht.html","i":"i238","x":"II Wann versteigert wird Zu jedem Jahresbeginn würfelt die Stadt, frühestens 1408: mit einem Viertel Wahrscheinlichkeit kommt es zu einer Versteigerung — im Mittel also alle vier Jahre; nur, wenn gerade keine andere läuft; und nur, wenn die Stadt überhaupt noch eine der drei Stätten selbst besitzt. Unter denen, die ihr gehören, entscheidet das Los. Was einmal verkauft ist, kommt nicht wieder unter"},{"p":"wissen-pacht.html","i":"i239","x":"III Was die Stätte wert ist, und das Mindestgebot Jede Stätte trägt zwei Zahlen mit sich: ihren Wert und das letzte Gebot. Am Anfang ist der Wert der Gebäudewert — die Hütte samt Räumen, Anbauten und Inhalt —, und als „letztes Gebot“ steht das Doppelte davon da, obwohl nie jemand geboten hat. Daraus rechnet die Stadt das Mindestgebot: das letzte Gebot, plus ein Anteil von Wert und letztem Gebot zu"},{"p":"wissen-pacht.html","i":"i240","x":"IV Wer mitbieten darf Höchstens acht Bieter. Zugelassen ist nur, wer in bar mindestens das Mindestgebot besitzt — Waren, Häuser und Schuldscheine zählen nicht — und wer nicht im Kerker sitzt. 1. Zuerst kommen alle Spieler, Menschen wie Mitspieler im Netz, die die Bedingungen erfüllen. 2. Die freien Plätze füllen dann die Computerdynastien und die wohlhabenden Bürger der Stadt auf — die reichsten z"},{"p":"wissen-pacht.html","i":"i241","x":"V Fünf Runden, ein Gulden Aufschlag Die Versteigerung hat fünf Runden. In jeder Runde gibt jeder, der noch dabei ist, ein Gebot ab oder steigt aus — wer einmal passt, ist draußen. Das höchste Gebot wird zum neuen Preis; bei Gleichstand gewinnt, wer früher in der Reihe steht. Nach jeder Runde außer der letzten steigt der Preis um einen einzigen Gulden über das bisher höchste Gebot. Bieten nur noch "},{"p":"wissen-pacht.html","i":"i242","x":"VI Wie die Computer bieten Ein Computer wirft nicht sein ganzes Vermögen in die Waagschale. Er nimmt sich jede Runde aufs Neue einen Betrag vor: etwa 30 bis 47 Prozent seines Bargelds, ausgewürfelt; höchstens das Doppelte des aktuellen Preises. Liegt dieser Betrag unter dem Preis, steigt er aus. Sonst bietet er nur mit einer gewissen Wahrscheinlichkeit — je knapper der Preis an seiner Grenze liegt"},{"p":"wissen-pacht.html","i":"i243","x":"VII Wohin das Geld geht Fall Stadtkasse Pachtmeister Es gibt einen Pachtmeister, ein anderer gewinnt 90 % 10 % Der Pachtmeister ersteigert selbst 90 % — Das Amt ist unbesetzt 100 % — Das Zehntel steht so auch im Amtstext. Das schönste Detail ist die zweite Zeile: Ersteigert der Pachtmeister selbst, zahlt er nur neun Zehntel — sein eigener Anteil wird gar nicht erst überwiesen. Als Pachtmeister bek"},{"p":"wissen-pacht.html","i":"i244","x":"VIII Zurück an die Stadt Eine ersteigerte Stätte lässt sich nicht gewöhnlich verkaufen. Statt des Verkaufsknopfs bietet das Gebäudemenü an, sie an die Stadt zu verkaufen, und zwar für die Hälfte von Wert und letztem Gebot zusammen. Wer die Mine für 8.200 Gulden ersteigert hat, bekommt also gut 5.260 zurück. Das Geld kommt dabei aus dem Nichts — die Stadtkasse wird nicht belastet, und sie kann auch"},{"p":"wissen-leben.html","i":"i245","x":"I Zwei Zähler, nicht einer Jede Figur trägt zwei getrennte Größen. Die Lebenskraft ist die Kerze im Charakterbogen: Sie steht mit zwölf Jahren auf vollen 1000 Punkten und brennt danach jedes Jahr ein Stück herunter. Sie wächst nie von allein nach. Daneben gibt es die Wunden. Sie kommen von Schlägen, Duellen, Unfällen — und, was niemand vermutet, auch von Krankheiten. Wunden heilen von selbst, und "},{"p":"wissen-leben.html","i":"i246","x":"II Das Tempo steht bei der Geburt fest Gewürfelt wird nicht der Tod, sondern das Tempo: Jede Figur bekommt bei der Geburt ihr eigenes, festes Brenntempo von rund 24 bis 37 Punkten je Jahr. Daraus folgt ein Sterbealter zwischen etwa 39 und 54 Jahren — wenn nichts dazwischenkommt. Es gibt keinen Todeswurf. Es gibt nur eine Kerze, die bei jedem verschieden schnell brennt. Wie gut das stimmt, zeigt ei"},{"p":"wissen-leben.html","i":"i247","x":"III Kinder Unter zwölf Jahren brennt gar nichts: Die Kerze jedes Kindes steht auf vollen 1000, und erst mit dem zwölften Geburtstag beginnt sie zu sinken. Dafür ist ein Kind zerbrechlich. Seine Widerstandskraft wächst von einem Viertel bis zwei Fünfteln bei der Geburt gleichmäßig auf den vollen Wert mit zwölf. Der Charakterbogen zeigt trotzdem eine volle Kerze — sichtbar wird der Unterschied erst,"},{"p":"wissen-leben.html","i":"i248","x":"IV Das Dach über dem Kopf verlängert das Leben Das ist der größte Hebel, den man selbst in der Hand hat — und im Spiel steht er nirgends. Die Ausbauten der Wohnstätte (offenes Feuer, Kamin, Vertäfelung, Tapeten, Wintergarten) bringen Punkte, und jeder volle Ausbau senkt das jährliche Brennen. Wohnstätte Punkte weniger Brennen je Jahr keine 0 — Haus 20 ¾ Bürgerhaus 30 1⅛ Villa 50 1⅞ Palazzo 80 3 Be"},{"p":"wissen-leben.html","i":"i249","x":"V Neun Krankheiten, und sie vergehen von selbst Pest, Ruhr, Lungenentzündung, Husten, Haarausfall, Angst im Dunkeln, Vergesslichkeit, Lachanfall, Knochenbruch. Jede hat eine Schwere, keinen bloßen Ja-Nein-Zustand, und man kann an mehreren zugleich leiden. Beim Ausbruch schlägt die Krankheit einmal zu, und zwar als Wunde, nicht als Verlust an der Kerze. Eine schwere Pest reißt eine Wunde von bis zu"},{"p":"wissen-leben.html","i":"i250","x":"VI Wie man überhaupt krank wird Es gibt sieben Wege. Von selbst geschieht es nur auf dreien: Weg wen es trifft wie oft Zufall des Jahres, schwerer nur Euch, nicht die Gegner zusammen gut 4 % je Runde Zufall des Jahres, leichter nur Euch, nicht die Gegner (in den 4 % enthalten) Siechtum in der Stadt nur, wer kein Dach hat 5 % je Jahr Die Pest Arbeiter, Meister, Hausherr nach der Stadtchronik Nebel "},{"p":"wissen-leben.html","i":"i251","x":"VII Die Pest kommt nicht zufällig Sie ist ein Ereignis der Stadtgeschichte und steht in den Chroniken an festen Jahren — sechsunddreißigmal in den sechzehn Chroniken des Spiels. Man kann ihr nicht davonlaufen und sie nicht heraufbeschwören, und es zieht immer nur eine Pest zugleich durch die Stadt. Die Chronik legt fest, wie viele Häuser sie heimsucht: eines bis zehn. Sichtbar wird sie als Zug von"},{"p":"wissen-leben.html","i":"i252","x":"VIII Wunden heilen, und zwar schnell Anders als die Kerze erholen sich Wunden von allein: jede Stunde um elf Prozent, zwischen sechs Uhr morgens und zehn Uhr abends. nach bleibt von der Wunde einer Stunde 89 % acht Stunden 39 % einem Spieltag 15 % zwei Spieltagen 2 % Eine Wunde von 100 Punkten ist nach gut anderthalb Tagen restlos fort. Wer also ein Duell oder einen Pestausbruch überlebt hat, brau"},{"p":"wissen-leben.html","i":"i253","x":"IX Was wirklich hilft Mittel was es bringt Medicus heilt die halbe Wundenlast — aber nur in der Hälfte der Fälle Elixier des Dr. Faustus ein Zehntel dessen, was von der Kerze noch übrig ist Kräuterschnaps mildert eine einzige Krankheit, die erste in der Reihe von der Pest an Wohnstätte bis zu sechs Jahre, wenn sie in gutem Zustand ist Versicherungsbulle holt Euch einmal nach dem Tod zurück — für v"},{"p":"wissen-leben.html","i":"i254","x":"X Wer sonst noch stirbt Bürger ohne Beruf. Ein Städter, der nie ein Handwerk und nie ein Amt hatte, stirbt mit 44 bis 47 Jahren — ganz gleich, wie viel Kerze er noch hat. Eure eigene Familie ist davon ausgenommen, die der Gegner nicht. Waisen in einer übervollen Stadt. Ist die Stadt zu 85 Prozent voll, sterben auch ungeschützte Waisen, gleich welchen Alters. In den gemessenen Partien wurde diese G"},{"p":"wissen-leben.html","i":"i255","x":"XI Vier Dinge, die anders sind, als sie aussehen Der Hauch des Verfalls verjüngt sein Opfer. Die Kunst des Totengräbers soll dem Opfer Jahre stehlen — tatsächlich setzt sie dessen Kerze auf volle 1000 zurück. Wer sie einsetzt, schenkt seinem Feind ein neues Leben. So steht es im Programm; am laufenden Spiel beobachtet ist es nicht. Und die Séance ebenso. „Je größer Euer Wunsch, um so mehr Lebenskr"},{"p":"wissen-werbung-und-ehe.html","i":"i256","x":"I Das Werben selbst kostet nichts „Um Ehepartner werben“ ist die billigste Handlung des ganzen Menüs: kein Aktionspunkt, keine Gebühr, kein Gulden. Verlangt wird nur, daß Ihr ledig seid — oder verwitwet. Wessen Gatte gestorben ist, darf sofort von neuem freien. Bezahlt wird genau eines, und das freiwillig: das Geschenk. Auch die Hochzeit kostet nichts. Die „Gebühr für Hochzeiten“, die im Kirchenme"},{"p":"wissen-werbung-und-ehe.html","i":"i257","x":"II Wie lange es dauert Die Dauer liegt zwischen 2 und 15 Jahren und setzt sich aus vier Posten zusammen: Posten Jahre ihr Alter: mit 15 Jahren +1 … mit 30 und älter −3 wie gut sie von Euch denkt — von ganz bis gar nicht +1 bis +6 ist sie reicher als Ihr? +1 bis +6 ihre Begabung (alle Talente zusammen) 0 bis +5 Zwischen 15 und 30 fällt der Altersposten gleichmäßig. Beim Vermögen zählt das der Umwor"},{"p":"wissen-werbung-und-ehe.html","i":"i258","x":"III Was „sie mag Euch“ wirklich heißt Der Posten „wie gut sie von Euch denkt“ ist Euer Ansehen bei ihr, und das Spiel rechnet es jedes Jahr frisch. Es setzt sich nicht nur aus der Zuneigung zusammen, sondern auch aus Dingen, an die man beim Freien nicht denkt: Euer Haus und Eure Ämter- und Zunftgebäude machen Eindruck. Der Glaube. Teilt sie Euren, steht Ihr ein paar Punkte besser da, sonst ein paa"},{"p":"wissen-werbung-und-ehe.html","i":"i259","x":"IV Neun Namen, und jedesmal andere Das Auswahlfenster zeigt neun Personen, drei mal drei, und unter jedem Namen die Werbedauer in Jahren. Gezogen werden sie bei jedem Öffnen neu aus der ganzen Stadt, gleichmäßig und ohne Vorliebe. Wer nicht zufrieden ist, macht das Fenster noch einmal auf. Gefällt Euch keiner der neun, oder ist jede Werbung zu lang: Fenster schließen und wieder öffnen. Es kostet n"},{"p":"wissen-werbung-und-ehe.html","i":"i260","x":"V Das Jahr der Werbung Einmal im Jahr, morgens um acht, rückt die Werbung voran: Wer wirbt je Jahr Ihr selbst 1 Jahr ein Haus der Konkurrenz 2 bis 3 Jahre ein Bürger der Stadt 1, in jedem vierten Fall 2 Die Konkurrenz wirbt also zwei- bis dreimal so schnell wie Ihr — es sei denn, Ihr schenkt. Die Werbung bricht ab, wenn einer von beiden stirbt oder in den Kerker kommt, wenn die Umworbene einem and"},{"p":"wissen-werbung-und-ehe.html","i":"i261","x":"VI Ein Geschenk im Jahr Das erste Angebot liegt erst nach dem ersten verstrichenen Jahr an, nicht gleich beim Beginn. Danach gibt es jedes Jahr genau eines: drei Geschenke zur Wahl, dazu „Das ist alles zu teuer!“. Wer ablehnt, hat das Angebot dieses Jahres verbraucht. Wer das Fenster nicht aufmacht, verliert es auch: Im nächsten Jahr liegt ein neues da, das alte ist fort. Reicht das Bargeld nicht,"},{"p":"wissen-werbung-und-ehe.html","i":"i262","x":"VII Was ein Geschenk bringt Jedes Geschenk hat eine Stufe von 0 bis 31, und jede Umworbene einen Titel von 0 (Unfreie) bis 9 (Reichsfürstin). Entscheidend ist allein, wie weit die Stufe über ihrem Titel liegt: Stufe über ihrem Titel spart 0 oder 1 — oder darunter nichts 2 bis 4 1 Jahr 5 bis 7 2 Jahre 8 und mehr 3 Jahre Mehr als drei Jahre bringt kein Geschenk, wie teuer es auch sei. Und der Preis "},{"p":"wissen-werbung-und-ehe.html","i":"i263","x":"VIII Die Antwort verrät den Gewinn Das Spiel sagt nie, wieviel ein Geschenk gebracht hat. Die Umworbene sagt es: sie … gespart weiß nicht, ob das ernst gemeint ist · schaut Euch ungläubig an · ist irritiert · lächelt unsicher · murmelt „Danke!“ 0 ist damit zufrieden · ist glücklich · nickt zufrieden · freut sich über das Geschenk 1 haucht Euch einen Kuß zu 1 oder 2 ist begeistert · schaut Euch bew"},{"p":"wissen-werbung-und-ehe.html","i":"i264","x":"IX Die zweiunddreißig Geschenke Stufe Geschenk 0 Ein Schuldschein 1 Ein heißer Stein zum Wärmen 2 Ein Brotmesser 3 Eine Küchenschürze 4 Ein Strauß schöner Rosen 5 Euer Lieblingskochbuch 6 Ein wohlriechendes Duftwasser 7 Ein Leibeigener 8 Ein Strauß edler Rosen 9 Ein Ausflug aufs Land 10 Ein Keuschheitsgürtel 11 Eine uralte Schatzkarte 12 Ein altgedientes Reitpferd 13 Einige Leibeigene 14 Ein zügel"},{"p":"wissen-werbung-und-ehe.html","i":"i265","x":"X Welche Geschenke Ihr zu sehen bekommt Angeboten werden drei aus einer Leiter von zwölf aufeinanderfolgenden Stufen. Wo sie beginnt, hängt an Eurem Amt — oder an dem Eures Vaters, wenn das höher ist: je zwei Amtsstufen eine Geschenkstufe höher. Ihr Leiter ohne Amt Stufe 0 bis 11 mittleres Amt 3 bis 14 eines der allerhöchsten Ämter 6 bis 17 Wer sein Amt verliert, freit weiter in alten Kreisen. Wer"},{"p":"wissen-werbung-und-ehe.html","i":"i266","x":"XI Was ein Geschenk kostet Der Preis hängt am Vermögen beider Seiten — Bargeld, Häuser und Waren zusammen — und an der Stufe. Wer weniger als tausend Gulden besitzt, wird wie mit tausend gerechnet. Ungefähre Preise in Gulden: Vermögen Stufe 0 Stufe 11 Stufe 17 beide arm 3 37 56 Ihr 100.000, sie arm 157 1.894 2.840 beide 500.000 1.562 18.750 28.125 Jede Stufe höher kostet gleich viel mehr: Stufe 11"},{"p":"wissen-werbung-und-ehe.html","i":"i267","x":"XII Das Wettrennen Um dieselbe Person dürfen beliebig viele zugleich werben; niemand wird daran gehindert. In einer Kölner Partie warben drei Männer zugleich um dieselbe Wilhelmine, einer davon der Spieler. Wer zuerst sein Ziel erreicht, bekommt die Zusage. Alle anderen fallen im nächsten Jahr heraus. Vom Nebenbuhler erfahrt Ihr erst, wenn Ihr verloren habt. In den Spieldateien steht ein Gerücht: "},{"p":"wissen-werbung-und-ehe.html","i":"i268","x":"XIII Verlobung und Hochzeit Mit der Zusage sind beide verlobt, und die Umworbene zieht in den Haushalt dessen, der geworben hat — wirbt eine Frau, zieht der Mann zu ihr. Den Nachnamen behält jeder. Die Kinder gehören fast immer zum Haus des Vaters; bei einer Konkurrentin, die sich einen Bürger genommen hat, tragen sie aber ihren Namen und gehören zu ihrem Haus. Die Hochzeit folgt etwa zwei Stunden"},{"p":"wissen-werbung-und-ehe.html","i":"i269","x":"XIV Der Erbe kommt fast sofort Die Trauung hat eine Wirkung, die nirgends steht: Sie stellt die Frau knapp über die Schwelle zur Empfängnis. Heiratet ein Spieler oder ein Haus der Konkurrenz, kommt das erste Kind schon im Jahr nach der Hochzeit. Solange die Werbung läuft, wird die Frau nicht schwanger; beim Spieler gibt sie erst der Hochzeitsfilm frei. Danach wächst die Bereitschaft jedes Jahr von"},{"p":"wissen-werbung-und-ehe.html","i":"i270","x":"XV Die Stadt heiratet mit Auch Bürger und die Häuser der Konkurrenz werben — in einer Kölner Partie entstanden in neunzehn Jahren zwanzig Bürgerehen. Sie wählen anders als Ihr: aus zwölf Gezogenen, und nur unter denen, die sie zu mindestens dreißig Prozent mögen. Ein Bürger fragt sich höchstens jedes vierte Jahr, ob er freit. Geschenke machen sie keine; dafür sind sie schneller. Um Euch selbst wir"},{"p":"wissen-werbung-und-ehe.html","i":"i271","x":"XVI Die Scheidung Erlaubt ab dem Titel Freiherr, solange der Gatte lebt. Sie kostet acht Aktionspunkte — die teuerste Handlung des Menüs. Das Fenster nennt zwölf Prozent des Vermögens. Gezahlt werden acht, in bar, an den Gatten. Die vier Prozent, „damit die Kirche alle Augen zudrückt“, bekommt niemand. Gerechnet wird vom ganzen Vermögen, Häuser und Waren eingeschlossen, Schulden nicht abgezogen — "},{"p":"wissen-werbung-und-ehe.html","i":"i272","x":"XVII Die Geliebte Anders als bei der Ehe darf die Auserwählte verheiratet sein; ausgeschlossen ist nur, wer schon eine Liaison hat. Eine Absage gibt es nicht: Wer in der Liste steht, sagt ja, und Euer Ansehen bei ihr steigt deutlich. Die Liebschaft kostet jedes Jahr zwei Aktionspunkte. Entdeckt wird sie nie; erst wenn Ihr sie beendet, verliert Ihr einmalig an Ansehen bei ihr, um so mehr, je länger"},{"p":"wissen-werbung-und-ehe.html","i":"i273","x":"XVIII Acht Ratschläge Öffnet das Auswahlfenster mehrmals und nehmt den Namen mit der kürzesten Zahl darunter. Es kostet nichts. Das Alter der Braut ist ein Tausch. Ab dreißig ist sie drei Jahre schneller zu haben — aber mit 38 bekommt sie keine Kinder mehr, und die Werbung selbst dauert auch. Seid reicher als ihr Haus. Dann kostet das Vermögen nur ein Jahr statt bis zu sechs. Pflegt Euer Ansehen b"},{"p":"wissen-steuern.html","i":"i274","x":"I Fünf Abgaben, einmal im Jahr Das Spiel kennt fünf Abgaben: Umsatzsteuer, Gildensteuer, Importzoll, Erbschaftsteuer und den Kirchenzehnt. Keine davon wird beim einzelnen Verkauf fällig. Alle werden einmal im Jahr abgerechnet, am Beginn der neuen Runde, und zwar grundsätzlich für jede Figur der Stadt — für Euch genauso wie für Eure Gegner. Die Rechnung ist für alle fünf dieselbe: Grundlage mal Ste"},{"p":"wissen-steuern.html","i":"i275","x":"II Umsatzsteuer oder Gildensteuer — nie beides Grundlage beider Steuern ist derselbe Betrag: alles, was Ihr im Lauf des Jahres verkauft habt. Gezählt wird der Erlös des Verkäufers, nicht der Einkauf. Nach der Abrechnung fängt die Summe wieder bei null an. Welche der beiden Steuern Ihr zahlt, entscheidet Euer Gewerk. Nur vier Gewerke haben eine Zunft: Schmiede, Steinmetze, Tischler und Parfumeure. "},{"p":"wissen-steuern.html","i":"i276","x":"III Der Zoll, der nichts vergißt Der Importzoll trifft nicht den Einkauf am Markt. Das, was Ihr am Markt kauft und verkauft, fällt unter die Umsatzsteuer. Grundlage des Zolls ist allein der Handel über die Import- und Exportlager, und zwar beide Seiten des Geschäfts gleich. Und dann folgt die eigentliche Überraschung: Diese Summe wird nie zurückgesetzt. Die Umsatzsteuer fängt jedes Jahr bei null a"},{"p":"wissen-steuern.html","i":"i277","x":"IV Die Erbschaftsteuer — wer knapp ist, zahlt nichts Stirbt das Haupt Eurer Familie und übernimmt ein Erbe, wird einmal Erbschaftsteuer fällig. Grundlage ist das ganze Vermögen des Verstorbenen: Bargeld, Gebäude und alles, was darin lagert. Bezahlt wird aber nur aus dem Bargeld des Erben. Und reicht das nicht für die volle Summe, zahlt er gar nichts. Die Steuer wird weder gestückelt noch gestundet"},{"p":"wissen-steuern.html","i":"i278","x":"V Der Kirchenzehnt gehört niemandem Die Umsatzsteuer, die Gildensteuer, den Zoll und die Erbschaftsteuer bekommt die Stadtkasse. Den Kirchenzehnt bekommt niemand. Weder der Bischof noch die Kirche noch die Stadt. Das Geld wird Euch abgezogen und verschwindet. Wer hätte das gedacht. Die anderen vier Abrechnungen schlagen zuerst die Stadtkasse auf. Die des Zehnts läßt genau diesen einen Schritt aus "},{"p":"wissen-steuern.html","i":"i279","x":"VI Die Miete der Arbeiter Eine sechste Abgabe zahlt Ihr nicht selbst: die Miete der Arbeiter. Jeder Arbeiter, der in einer Arbeiterunterkunft wohnt, zahlt einmal im Jahr an die Stadtkasse. Wie viel, hängt am Mietpreisniveau, das der Rat festlegt: Mietpreisniveau sehr hoch hoch mittel niedrig lausig Miete im Jahr 14 13 12 11 10 Die Miete geht immer an die Stadt. Auch dann, wenn die Unterkunft einem"},{"p":"wissen-steuern.html","i":"i280","x":"VII Was die Ämter einbringen Jedes Amt bringt ein festes Jahreseinkommen. Der Amtstext nennt es eine Aufwandsentschädigung, den Betrag aber nennt er nicht. Hier ist er: Ebene untere Stufe mittlere Stufe Spitze Stadtdiener, Schergen, Informanten 500 700 1.000 Stadtrat 2.000 2.500 3.000 Kirche 2.000 2.500 3.000 Land 5.000 7.000 10.000 Reich 20.000 30.000 50.000 Im Stadtrat bekommen also Baumeister, "},{"p":"wissen-steuern.html","i":"i281","x":"VIII Die Pacht und der Anteil des Pachtmeisters Eine Jahrespacht gibt es nicht. Pachtgüter werden versteigert, im Mittel etwa alle vier Jahre. Vom Zuschlag bekommt die Stadt 90 % und der Pachtmeister 10 %. Ist das Amt unbesetzt, geht alles an die Stadt. Ersteigert der Pachtmeister selbst, zahlt er nur die 90 % an die Stadt, seinen eigenen Zehnten spart er sich. Ob diese Teilung auch dann läuft, we"},{"p":"wissen-steuern.html","i":"i282","x":"IX Wohin die Gebühren gehen — fast immer ins Nichts Neben den Steuern zahlt Ihr ständig für Dienste. Fast all dieses Geld bekommt niemand: Bauen, Aufwerten und Ausbauen: Das Geld verschwindet. Im Gesetzestext steht, das Baugeld sei „an die Stadt abzuführen\", doch eine Buchung steht nicht dahinter. Aufwerten kostet drei Zehntel des Grundpreises der nächsten Stufe. Karren kaufen und ausbessern, Reno"},{"p":"wissen-steuern.html","i":"i283","x":"X Die Stadtkasse wird nie leer Was fließt also in die Stadtkasse? Umsatz- und Gildensteuer, Zoll, Erbschaftsteuer, die Miete der Arbeiter, der größte Teil der Pacht und das Geld für das Bürgerrecht. Keine der hier beschriebenen Zahlungen geht aus ihr heraus — selbst die Amtsgehälter kommen woanders her. Trotzdem kann die Kasse nicht leer werden. Fällt der Bestand unter 160.000 Gulden, bekommt die "},{"p":"wissen-schenke.html","i":"i284","x":"I Wer Gast ist — und wann gezählt wird Den ganzen Tag gehen Leute in Eure Schenke ein und aus. Gezählt wird davon nur, wer abends um halb elf dort steht. Einmal am Spieltag — und ein Spieltag ist eine ganze Runde — geht das Spiel die Leute der Stadt durch: die eine Hälfte um 22:30, die andere um 22:45, eine halbe Stunde bevor die Schenke um 23 Uhr schließt. Wer um Mittag dort saß und wieder ging, "},{"p":"wissen-schenke.html","i":"i285","x":"II Welche Schenke er wählt — Ausstattung gegen Weg Unter allen Schenken der Stadt nimmt der Arbeiter die mit dem besten Wert aus zwei Teilen: wie nah sie an seiner Wohnung liegt, und wieviel „Gästeaufkommen“ ihre Ausstattung trägt. Beide Teile sind gleich schwer: Die volle Ausstattung wiegt so viel wie der ganze Weg quer durch die Stadt. Stück Schenke Wirtshaus Gasthaus Schöne Stühle 15 15 15 Eise"},{"p":"wissen-schenke.html","i":"i286","x":"III Was ein Gast kauft und zahlt Im Schankraum verkauft Ihr genau zwei Dinge: Körnermahlzeit und Dünnbier, und nur, was in der Lagerfläche liegt. Starkbier, Fahnenbräu, Schädelbrand und Kräuterschnaps fragt kein Gast an — die sind Marktware. Der Schankpreis ist das Anderthalbfache des Marktpreises in der Stadt. Jeder Gast kauft ein Stück: Kann er sich das Teurere leisten und liegt beides da, wirft"},{"p":"wissen-schenke.html","i":"i287","x":"IV Warum die Schenke in den ersten Jahren eine Garküche ist Ob ein Arbeiter sich etwas leisten kann, hängt an dem, was er in der Tasche trägt. Gemessen in den Spielständen, mit den billigsten und teuersten Preisen, die je vorkamen: Jahr Bargeld eines Arbeiters (Mitte) kann die Mahlzeit zahlen kann das Dünnbier zahlen 1404 279 52 – 69 % 0 – 8 % 1405 357 67 – 88 % 0 – 14 % 1412 560 81 – 93 % 33 – 65"},{"p":"wissen-schenke.html","i":"i288","x":"V Das Würfelspiel „17“ — wann überhaupt jemand am Tisch sitzt Der Spieltisch (70 Gulden, schon in der Schenke) bietet ein Würfelspiel gegen einen Fremden. Ob einer dasitzt, ist an drei Dinge gebunden: Es muß nach 12 Uhr sein. Euer Vermögen — Bargeld plus Wert Eurer Gebäude — muß mindestens 10.000 Gulden betragen. Darunter ist der Tisch immer leer. Und Ihr müßt Glück haben, und das nimmt im Lauf de"},{"p":"wissen-schenke.html","i":"i289","x":"VI Wie die Würfel schummeln — nach Talent Die Regeln im Spieltext stimmen: drei Würfel verdeckt, Dreierpasch gewinnt sofort, dann weiterwürfeln oder stehenbleiben, beides mit Erhöhung, wer 18 erreicht, verliert, bei Gleichstand gewinnt die Bank. Was der Text nicht sagt: Die Würfel sind nicht fair. Bei Nacht und Nebel — das Talent, das die Hilfe nennt — verbiegt jeden Würfel: Euer Talent Eins Sechs"},{"p":"wissen-schenke.html","i":"i290","x":"VII Der Gegner gibt nie auf — und sein Geld gibt es nicht Aufgeben tut der Fremde nie. Das Spiel hat einen Weg dafür vorgesehen, aber die Bedingung kann nie erfüllt werden. Wartet also nicht darauf, daß er die Nerven verliert. Er zieht nach einer festen Regel: Fehlen ihm mehr als fünf bis zur 17, würfelt er immer; sonst wagt er es umso eher, je mehr noch fehlt. Schwache Gegner wagen mehr als stark"},{"p":"wissen-schenke.html","i":"i291","x":"VIII Die Dunkle Ecke und der Stammtisch Die Dunkle Ecke (100 Gulden, ab dem Wirtshaus) — dort sitzt ein finsterer Geselle, dem Ihr Spitzel abkaufen könnt. Er bietet bis zu drei offene Beweise gegen Missetäter an, gegen Geld. Neben dem Gerücht ist das der einzige Weg, nach einer Tat noch an Beweise zu kommen. Zwei Dinge sagt Euch keiner: Seine Spitzel finden nur Taten ab dem Tag, an dem Ihr sie los"},{"p":"wissen-schenke.html","i":"i292","x":"IX Was es nur im Hilfetext gibt Der Text verspricht Im Spiel Würfeln gegen einen oder mehrere Konkurrenten Gibt es nicht. Es gibt nur den Fremden; ein Spiel gegen Mitspieler hat das Programm nirgends. Zimmer vermieten Kein Menü dafür. Die Zimmertafel im Schankraum ist Kulisse. Einzeltische senken das Risiko einer Kneipenschlägerei Eine Schlägerei startet niemand; die Szenen liegen im Archiv, kein "},{"p":"wissen-schenke.html","i":"i293","x":"X Kleinigkeiten, die man nicht sieht Frauen dürfen eine Schenke führen, wie jedes andere Gewerbe auch. Wirte haben keine Zunft und kein Zunfthaus. Der Lohn des Schankpersonals ist derselbe wie überall: 112 Gulden für den Gesellen, 56 für den Lehrling je Runde, bei mittlerem Lohnniveau. Die Schenke hat Platz für 2, das Wirtshaus für 3, das Gasthaus für 4 Leute. Geöffnet ist von 12 bis 23 Uhr. Ein B"},{"p":"wissen-altern-lassen.html","i":"i294","x":"I Worum es geht Vom Friedhof aus — der Hilfetext sagt: „von den Ruinen aus“ — schickt Ihr einen Eurer Gehilfen in die Stadt. Er sucht eine bestimmte Person, berührt sie, und sie soll „um einige Jahre“ altern. Im Menü heißt die Aktion „Jemanden altern lassen“, in der Überschrift Hauch des Verfalls. Kosten 4 Aktionspunkte — geprüft und auch abgezogen. Kein Geld Trefferaussicht ein Vergleich im Talen"},{"p":"wissen-altern-lassen.html","i":"i295","x":"II Der Ablauf Der Auftrag läuft in fünf Schritten: Losschicken. Ihr lest, Euer Gehilfe „macht sich murrend auf den Weg“. Suchen. Das Opfer wird dort gesucht, wo es wohnt — sonst an seiner Arbeitsstelle, sonst irgendwo. Ist es nicht zu finden, endet der Auftrag. Berühren. Hier fällt die Entscheidung: der Wurf gegen die Aussicht und, bei Erfolg, die Rechnung der Jahre. Zurückkehren. Berichten. Ihr e"},{"p":"wissen-altern-lassen.html","i":"i296","x":"III Was es kostet Vier Aktionspunkte. Das Menü prüft, ob Ihr sie habt, und der Auftrag zieht sie beim Start tatsächlich ab. Gulden kostet es nicht — weder der Spielerweg noch der Weg, den die Gegner gehen. Dasselbe gilt am Friedhof für das Erschaffen und Verbessern von Gehilfen, die Séance und die Heimsuchung: Dort zahlt Ihr mit Aktionspunkten, nicht mit Geld."},{"p":"wissen-altern-lassen.html","i":"i297","x":"IV Die Trefferaussicht Es gibt keinen Grundwert. Die Aussicht ist ein Vergleich im Talent Bei Nacht und Nebel — mit derselben Formel, die das Spiel für alle seine Übergriffe benutzt, von der Sabotage bis zum Anschwärzen. Mit a als Talent des Gehilfen und v als Talent des Opfers, beide von 0 bis 1: Aussicht = 0,2·a² + 0,3·a − 0,2·v − 0,3·v² + 0,5 Die Anzeige zeigt höchstens sechs Sterne, in halben "},{"p":"wissen-altern-lassen.html","i":"i298","x":"V Wie viele Jahre gestohlen werden Die Zahl hängt nicht am Gehilfen, sondern am Friedhof: an seinem baulichen Zustand und an seiner Ausbaustufe. Dazu kommt ein Wurf von 0 bis 2. Friedhof Ausbau bringt Zustand unter 50 % 50 bis 99 % 100 % Totenfeld +2 2 bis 4 3 bis 5 4 bis 6 Gottesacker +4 4 bis 6 5 bis 7 6 bis 8 Friedhof +6 6 bis 8 7 bis 9 8 bis 10 Eine Ausbaustufe ist zwei Jahre wert, ein gepfleg"},{"p":"wissen-altern-lassen.html","i":"i299","x":"VI Was beim Opfer geschieht Jede Figur trägt eine Lebensuhr, die mit den Jahren abläuft. Der Hauch greift in sie ein — aber verkehrt herum. Ein Fehler des Originals. Das Spiel reicht die gestohlenen Jahre an eine Stelle weiter, die ein Lebensalter erwartet und die Uhr auf dieses Alter stellt, statt etwas abzuziehen. Jedes Alter unter zwölf heißt dort: Uhr auf den vollen Anfangswert. Und der Hauch "},{"p":"wissen-altern-lassen.html","i":"i300","x":"VII Der Gehilfe Geschickt wird der erste Gehilfe, den das Spiel in seiner Figurenliste findet — ohne Vergleich der Talente. Wer mehrere hat und nur einen geschult, kann nicht steuern, wer geht. Nach einem Treffer hängt der Bericht manchmal einen zweiten Satz an: Euer Gehilfe sei „ebenfalls ein Opfer der Alterung geworden“. Wie oft, richtet sich nach seinem Talent in Handwerkskunst. Die Meldung ver"},{"p":"wissen-altern-lassen.html","i":"i301","x":"VIII Die Meldungen An wen Wann Was Opfer getroffen „Das Alter holt Euch ein…“ — mit einer von drei Wendungen Opfer entkommen „Eine gruselige Begegnung…“ Ihr Erfolg der Gehilfe kehrt zurück, am „freudigen Grunzen“ zu erkennen Ihr Fehlschlag er „traut sich nicht, Euch anzusehen“ Die drei Wendungen der Erfolgsmeldung — Haut, Haarpracht, Knochen — werden ausgewürfelt. Sie sagen nichts darüber, wie vie"},{"p":"wissen-altern-lassen.html","i":"i302","x":"IX Die Sperre und das Gesetz Wer es zweimal gegen dieselbe Person versucht, liest „in dieser Runde bereits“. Das Programm prüft aber nicht die Runde, sondern ob Euer letzter Auftrag gegen sie noch läuft. Ist der Gehilfe zurück, geht der nächste — auch in derselben Runde. Schon beim Losschicken legt das Spiel die Tat als Nekromantie an; ob sie als Tat zählt, prüft es dabei gegen das Stadtgesetz. Zu"},{"p":"wissen-altern-lassen.html","i":"i303","x":"X Wie wehrhaft die Opfer sind Ausgezählt an allen 302 Figuren einer Stadt im Jahr 1419 und ihren fünf Talenten: Gut die Hälfte aller Werte (53 %) zeigt höchstens anderthalb Sterne. Der Mittelwert liegt bei gut zwei Sternen, die Mitte der Reihe bei anderthalb. Die einfachste Figurenart, zu der die Arbeiter gehören, kommt im Mittel auf knapp anderthalb Sterne; einige andere Arten kommen auf rund dre"}];
